/* 인사교 알아보기(10-14 교체: 전달본 style.css). 헤더 · 푸터 · 본문 바로가기 · 자체 메뉴 규칙과 :root 색 변수(--blue · --ink · --muted · --line · --paper)는 빼고 사이트 공통(common/)을 씀. 이미지는 webp, 글꼴은 common/assets/fonts */
/* styles.css */:root{--pale:#eef3ff;--radius:5px;font-family:Pretendard,"Noto Sans KR","Malgun Gothic",sans-serif;color:var(--ink);background:var(--paper);font-synthesis:none;scroll-behavior:smooth;}*{box-sizing:border-box}body{margin:0}button, input, select{font:inherit}button, a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:inherit;text-decoration:none}button{color:inherit}img{display:block;width:100%;object-fit:cover}button:focus-visible, a:focus-visible, summary:focus-visible, select:focus-visible{outline:3px solid #ed961a;outline-offset:5px}.wrap{width:min(1360px,calc(100% - 112px));margin-inline:auto}.button{display:inline-flex;justify-content:space-between;align-items:center;gap:34px;border:1px solid var(--blue);border-radius:4px;padding:17px 22px;background:var(--blue);color:#fff;font-size:15px;font-weight:600;line-height:1.3;transition:background .2s,transform .2s}.button:hover{background:#0739cb;transform:translateY(-2px)}.button span{font-size:22px;font-weight:400}.button.small{padding:11px 17px;font-size:14px;gap:23px}.eyebrow{font-family:Arial,sans-serif;font-size:12px;font-weight:600;letter-spacing:1.7px;display:block}h1{margin:0;font-size:clamp(48px,5.15vw,76px);line-height:1.2;letter-spacing:-.065em;font-weight:720}h1 em{color:var(--blue);font-style:normal}.down-circle{display:flex;justify-content:center;align-items:center;border:1px solid #a9afb1;width:27px;height:27px;border-radius:100%;font-size:16px}.section{padding-block:85px}h2{font-size:34px;line-height:1.3;letter-spacing:-1.4px;margin:0;font-weight:680}.footer-top{display:flex;justify-content:space-between;align-items:center;padding-bottom:35px;border-bottom:1px solid var(--line)}.footer-top>span{font-size:20px;font-weight:650;letter-spacing:-.5px}.footer-top>a:last-child{font-size:13px}dialog{border:0;padding:0;width:min(860px,calc(100% - 32px));max-height:90dvh;border-radius:10px;box-shadow:0 20px 80px #05172838;overscroll-behavior:contain;background:var(--paper);color:var(--ink)}dialog::backdrop{background:#08131ba8;backdrop-filter:blur(5px)}.notice{font-size:14px;line-height:1.8;background:var(--pale);padding:17px 20px;border-radius:4px;color:#3d5490}[hidden]{display:none!important}@media(max-width:1100px){.wrap{width:calc(100% - 64px)}h1{font-size:57px}}@media(max-width:760px){.wrap{width:calc(100% - 40px)}.button.small{padding:9px 12px;font-size:12px;gap:14px}h1{font-size:clamp(42px,10.5vw,66px)}.section{padding-block:58px}h2{font-size:28px;letter-spacing:-1px}.footer-top{flex-wrap:wrap;gap:24px}.footer-top>span{font-size:16px}}@media(prefers-reduced-motion:reduce){:root{scroll-behavior:auto}*, *:before, *:after{animation:none!important;transition:none!important}}/* experience.css */
/* Immersive editorial direction: edge-to-edge physical scene, oversized type, chapter transitions. */
:root{--blue:#1646f2;--ink:#141b26;--paper:#f7f8f5;--muted:#636a77;scroll-padding-top:24px}.immersive-hero{overflow:hidden;background:#092787;color:#fff;isolation:isolate}.scene-background{position:absolute;inset:-3%;background:#102d80 url('../assets/coding.webp') center/cover no-repeat;z-index:-3;transform:scale(1.02);will-change:transform;}.scene-shade{position:absolute;inset:0;}.hero-masthead{position:absolute;top:82px;left:2.7%;right:45px;line-height:.82}.hero-masthead>span{display:block;font-family:Arial,sans-serif;font-size:11px;text-align:center;margin-bottom:16px;font-weight:600;letter-spacing:.5px}.hero-masthead>div{font-family:Arial,Helvetica,sans-serif;font-weight:850;font-size:clamp(70px,15.7vw,240px);letter-spacing:-.068em;white-space:nowrap}.scene-copy{position:absolute;text-shadow:0 2px 25px #06194150}.scene-copy>.eyebrow{font-family:inherit;font-size:12px;letter-spacing:.3px;margin-bottom:19px;color:#ccdcff}.scene-copy h1{line-height:1.45;letter-spacing:-1.3px;font-weight:570}.scene-copy p{font-size:15px;line-height:1.8;color:#e5ebff;margin-top:20px}.glass-note{position:absolute;left:3%;bottom:40px;width:238px;padding:23px;background:#c8e4ff15;border:1px solid #ffffff45;backdrop-filter:blur(12px);transition:background .25s}.glass-note:hover{background:#c8e4ff27}.glass-note>.eyebrow{font-size:10px;letter-spacing:.7px;opacity:.7}.glass-note>strong{display:block;font-size:23px;line-height:1.4;letter-spacing:-.6px;font-weight:600;margin:17px 0 28px}.glass-note>div{border-top:1px dashed #ffffff73;padding-top:16px;display:flex;justify-content:space-between;align-items:end}.glass-note>div>span:first-child{font-size:11px;line-height:1.6;color:#dae2f1}.glass-note>div>span:last-child{font-size:27px}.scene-scroll{position:absolute;left:50%;transform:translateX(-50%);bottom:29px;display:flex;align-items:center;gap:11px;font:10px Arial,sans-serif;letter-spacing:1px;white-space:nowrap}.scene-scroll .down-circle{border-color:#ffffff61}.filters{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:32px 0 25px}.learning-heading{font-size:clamp(43px,6.2vw,90px);line-height:1.16;letter-spacing:-.055em;margin:0 0 35px}.learning-heading>span{color:#87a9ff}.career-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:40px;gap:30px}.career-heading h2{font-size:clamp(40px,5vw,66px);letter-spacing:-.05em}.career-heading p{font-size:14px;color:var(--muted);line-height:1.8}
@media(max-width:1100px){.hero-masthead{top:94px}.glass-note{width:214px;bottom:40px}.glass-note>strong{font-size:21px}}
@media(max-width:760px){.hero-masthead{left:5%;right:5%}.hero-masthead>span{text-align:left;font-size:9px;letter-spacing:1px;margin-bottom:17px}.hero-masthead>div{font-size:15.7vw;letter-spacing:-.075em}.scene-background{background-position:43% center}.scene-copy h1{line-height:1.4;letter-spacing:-1.1px}.scene-copy p{line-height:1.7;}.glass-note>.eyebrow{font-size:8px}.glass-note>div{padding-top:10px}.glass-note>div>span:last-child{font-size:20px}.scene-scroll .down-circle{font-size:13px}.filters{gap:7px;margin:26px 0;flex-wrap:nowrap;overflow-x:auto;padding:2px 2px 12px}.learning-heading{font-size:47px}.career-heading{align-items:start;flex-direction:column;gap:15px}.career-heading h2{font-size:37px}.career-heading p{margin:0;font-size:14px}}.scene-background{background-image:url('../assets/hero-scene.webp')}/* scene.css */
.scene-runway{position:relative;height:330svh;min-height:2200px}.immersive-hero{position:sticky;top:0;height:100svh;min-height:680px;max-height:none}.scene-background{transition:opacity .7s}.scene-shade{z-index:0;pointer-events:none;background:linear-gradient(180deg,#030c271c,transparent 30%,#02091808 70%,#030d2b30)}.hero-masthead{pointer-events:none}.scene-copy{left:65%;width:29%;top:43%}.scene-copy h1{font-size:clamp(22px,2.4vw,38px)}.glass-note, .scene-scroll, .scene-copy, .hero-masthead{z-index:1}
@media(min-width:1200px){.hero-masthead>div{font-size:15.6vw}.hero-masthead{right:42px}.scene-copy{left:65%}}
@media(max-width:1100px) and (min-width:761px){.scene-copy{left:66%;width:28%;top:43%}.scene-copy h1{font-size:25px}.scene-copy p{font-size:13px}.glass-note{width:200px;padding:19px}.glass-note>strong{font-size:20px}}
@media(max-width:760px){.scene-runway{height:290svh;min-height:0}.immersive-hero{height:100svh;min-height:760px}.hero-masthead{top:96px}.scene-copy{left:7%;top:53%;width:85%;max-width:85%}.scene-copy h1{font-size:27px}.scene-copy p{font-size:12px;margin-top:13px}.scene-copy .eyebrow{font-size:10px;margin-bottom:10px}.glass-note{left:7%;bottom:67px;width:178px;padding:13px}.glass-note>strong{font-size:14px;line-height:1.4;margin:9px 0 11px}.glass-note>div>span:first-child{font-size:8px}.scene-scroll{bottom:24px;left:7%;transform:none;font-size:8px}.scene-scroll .down-circle{width:21px;height:21px}.scene-shade{background:linear-gradient(180deg,transparent 40%,#03123542 65%,#03123560)}}
@media(prefers-reduced-motion:reduce){.scene-runway{height:260svh}.scene-background{transition:none}}.immersive-hero{overflow:clip}/* still-scene.css */
/* Keep the original photographic opening instead of replacing it with WebGL. */
.scene-still .scene-runway{
  height: auto;
  min-height: 0;
}.scene-still .immersive-hero{
  position: relative;
}.scene-still .scene-background{
  opacity: 1;
  transition: none;
  will-change: auto;
}

@media (max-width: 380px) {.scene-still .scene-copy{
    top: auto;
    bottom: 255px;
  }.scene-still .glass-note{
    width: 49%;
  }
}/* about.css */
@font-face{ font-family: 'School Pretendard'; src: url('../../common/assets/fonts/Pretendard-Regular.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'School Pretendard'; src: url('../../common/assets/fonts/Pretendard-Bold.woff2') format('woff2'); font-weight: 700; font-display: swap; }
@font-face { font-family: 'School Pretendard'; src: url('../../common/assets/fonts/Pretendard-Black.woff2') format('woff2'); font-weight: 900; font-display: swap; }
@font-face { font-family: 'School Paperlogy'; src: url('../../common/assets/fonts/Paperlogy-9Black.woff2') format('woff2'); font-weight: 900; font-style: normal; font-display: swap; }.school-about{ --about-blue: #244cd2; --about-ink: #13203c; --about-muted: #657087; --about-line: #d8dfeb; --about-paper: #f8f9fc; scroll-behavior: smooth; }.school-about body{ font-family: 'School Pretendard', sans-serif; color: var(--about-ink); background: var(--about-paper); line-height: 1.65; }.school-about h1, .school-about h2, .school-about h3, .school-about h4, .school-about p, .school-about figure{ margin: 0; }.school-about h1, .school-about h2, .school-about h3, .school-about h4{ word-break: keep-all; }.school-about button, .school-about input{ font: inherit; }.school-about a:focus-visible, .school-about button:focus-visible{ outline: 3px solid #58d4fc; outline-offset: 5px; }.school-about .hero-masthead{ top: 100px; left: 3%; right: 3%; }.school-about .hero-masthead > span{ display: block; margin-bottom: 20px; font-family: 'School Pretendard', sans-serif; font-size: 12px; }.school-about .hero-masthead h1{ font-family: 'School Paperlogy', 'School Pretendard', sans-serif; font-size: clamp(42px, 11.3vw, 220px); font-weight: 900; font-synthesis: none; letter-spacing: -.03em; line-height: 1.05; white-space: nowrap; text-align: center; color: #fff; }.school-about .scene-background{ background-image: url('../assets/hero-cap-enlarged-fit-desktop-2x.webp'); filter: brightness(.82) saturate(.78); }.school-about .scene-copy h2{ font-size: clamp(24px, 2.2vw, 38px); letter-spacing: -.045em; line-height: 1.5; color: #fff; }.school-about .scene-copy p{ margin-top: 23px; color: #d9e5ff; font-size: 14px; }.school-about .scene-copy .eyebrow{ color: #d5e3ff; }.school-about .glass-note strong{ font-family: 'School Pretendard', sans-serif; font-weight: 900; letter-spacing: -.04em; }.school-about .scene-scroll{ font-family: 'School Pretendard', sans-serif; }.school-about .scene-scroll{ font-size: 12px; }.about-wrap{ width: min(1120px, calc(100% - 96px)); margin-inline: auto; }.about-paper{ background: var(--about-paper); }.about-section{ padding-top: 100px; padding-bottom: 108px; scroll-margin-top: 76px; }.micro-label{ display: block; margin-bottom: 17px; font-size: 11px; font-weight: 700; letter-spacing: .025em; color: var(--about-blue); }.intro-feature{ display: grid; grid-template-columns: 1fr 1.05fr; gap: 60px; align-items: center; }.school-about .intro-purpose h3{ font-size: clamp(26px, 2.7vw, 38px); font-weight: 900; letter-spacing: -.05em; line-height: 1.5; }.intro-purpose h3 em{ color: var(--about-blue); font-style: normal; }.intro-purpose > p{ margin-top: 24px; font-size: 16px; color: var(--about-muted); line-height: 1.9; word-break: keep-all; }.partner-heading h3{ font-size: 21px; font-weight: 900; letter-spacing: -.025em; }.why-school ol{ list-style: none; margin: 0; padding: 0; }.why-school ol{ margin-top: 15px; }.why-school li{ display: flex; gap: 18px; padding: 16px 0; }.why-school li > span{ color: var(--about-blue); font-size: 12px; font-weight: 700; }.why-school strong{ font-size: 16px; }.why-school p{ margin-top: 5px; font-size: 13px; color: var(--about-muted); }.partner-block{ margin-top: 70px; padding: 30px 0 0; border-top: 1px solid var(--about-line); }.partner-heading{ display: flex; align-items: center; gap: 25px; }.partner-heading p{ font-size: 12px; color: var(--about-muted); }

@media (max-width: 1100px) {.about-wrap{ width: calc(100% - 72px); }.intro-feature{ gap: 40px; }
}
@media (max-width: 800px) {.school-about .hero-masthead h1{ font-size: 11.4vw; }.school-about .hero-masthead{ left: 4%; right: 4%; }.school-about .scene-copy{ left: 61%; width: 34%; }.school-about .scene-copy h2{ font-size: 23px; }.school-about .scene-copy p{ font-size: 12px; }.about-wrap{ width: calc(100% - 48px); }.about-section{ padding-block: 74px; scroll-margin-top: 68px; }.intro-feature{ gap: 30px; }.intro-purpose > p{ font-size: 14px; }.school-about .intro-purpose h3{ font-size: 26px; }
}
@media (min-width: 601px) and (max-width: 900px) and (max-aspect-ratio: 1/1) {.school-about .scene-background{ inset: 0; transform: none; background-image: url('../assets/hero-cap-enlarged-fit-mobile-2x.webp'); background-size: cover; background-position: center; }.school-about .scene-copy{ left: 67%; width: 30%; }
}
@media (max-width: 600px) {.school-about .immersive-hero{ min-height: 760px; }.school-about .scene-background{ inset: 0; transform: none; background-image: url('../assets/hero-cap-enlarged-fit-mobile-2x.webp'); background-size: auto calc(100% + 280px); background-position: center bottom; }.school-about .hero-masthead{ top: 103px; left: 4%; right: 4%; }.school-about .hero-masthead > span{ font-size: 9px; margin-bottom: 19px; }.school-about .hero-masthead h1{ font-size: 11.4vw; letter-spacing: -.03em; }.school-about .scene-copy{ top: auto; bottom: 275px; left: 7%; width: 86%; max-width: 86%; }.school-about .scene-copy h2{ font-size: 27px; line-height: 1.45; }.school-about .scene-copy p{ font-size: 12px; margin-top: 12px; }.school-about .glass-note{ left: 7%; bottom: 67px; width: 49%; padding: 14px; }.school-about .glass-note strong{ font-size: 16px; line-height: 1.45; }.school-about .glass-note > div{ margin-top: 14px; padding-top: 12px; }.school-about .glass-note > div > span:first-child{ font-size: 9px; }.school-about .glass-note .eyebrow{ font-size: 8px; }.school-about .scene-scroll{ font-size: 10px; }.about-wrap{ width: calc(100% - 40px); }.about-section{ padding-block: 57px; scroll-margin-top: 63px; }.intro-feature{ grid-template-columns: 1fr; }.school-about .intro-purpose h3{ font-size: 30px; }.intro-purpose > p{ font-size: 15px; }.partner-block{ margin-top: 45px; }.partner-heading{ display: block; }.partner-heading p{ margin-top: 6px; }
}
@media (max-width: 360px) {.school-about .immersive-hero{ min-height: 800px; }.school-about .scene-background{ background-size: auto calc(100% + 310px); }.school-about .glass-note strong{ font-size: 14px; }
}
@media (prefers-reduced-motion: reduce) {.school-about{ scroll-behavior: auto; } }
/* section-navigation.css */
/* 오른쪽 목차(밝은 화면용) — 지원 전 체크 시안(.sec-float)의 모션(이징 · 시간)을 따랐어요.
   평소에는 섹션 수만큼 사선만 있고 지금 섹션은 파란 사선이에요. 사선에 마우스를 올리면 그 아래로 섹션 이름(세로 글씨)이 드러나고
   이어서 짧은 선이 자라나요(.is-open, script.js). 목차는 헤더 아래 화면 세로 가운데에 있고, 펼칠 때도 가운데를 지키며 위아래로 함께 늘어나요.
   첫 화면(파란 히어로)에서는 숨기고 밝은 본문이 올라오면 나타나요. */
.section-navigation{ display: none; }

@media (min-width: 1200px) {.section-navigation{
    /* --rail-step: 사선 하나가 차지하는 칸 높이(사선 사이 간격) */
    --rail-ease: cubic-bezier(.22, .61, .36, 1); --rail-step: 42px;
    /* 사선 칸을 48px로 넓힌 만큼(양옆 2px) 오른쪽 여백을 줄여, 보이는 사선 위치는 그대로예요. */
    display: block; position: fixed; top: calc(50% + 36px); right: calc(clamp(14px, 2.2vw, 36px) - 2px); z-index: 20;
    opacity: 0; visibility: hidden; transform: translate(8px, -50%);
    transition: opacity .4s var(--rail-ease), transform .4s var(--rail-ease), visibility .4s;
  }.section-navigation.is-visible{ opacity: 1; visibility: visible; transform: translate(0, -50%); }/* 목차 둘레에 보이지 않는 마우스 영역을 조금 두고, 그 안에서는 같은 높이의 사선으로 판정·클릭돼요(script.js). */
  .section-navigation::before{ content: ''; position: absolute; inset: -8px -10px; cursor: pointer; }/* 사선 칸: 사선 사이 빈틈까지 칸이 채워서(빈틈 없음) 사선 위아래 근처 어디에 있어도 그 사선으로 잡혀요. */
  /* 섹션 이름: 접혀 있을 때는 높이 0, 펼치면 이름 길이(--label-h, script.js가 잼)만큼 자라나요. */
  .about-has-section-nav .about-wrap{ width: min(1120px, calc(100% - 288px)); margin-inline: auto; }.about-has-section-nav .about-section{ scroll-margin-top: 28px; }.school-about.about-has-section-nav .scene-copy{ left: 63%; width: 21%; }}

@media (prefers-reduced-motion: reduce) {.section-navigation{ transition: none; }}/* intro-content.css */
/* School introduction: centered overview, then connected partners. */
