check/js/check.js:
/* =========================================================
   지원 전 체크: 움직임만(본문은 index.html)
   10-13: 사용자 제공 아티팩트 '인사교 A to Z'의 #/check 화면으로 교체. 아티팩트 script의 setupSecFloat · setupCheck를 옮김
   - 위치 이동: 섹션 제목이 헤더 + 하위 메뉴 바 아래 64px(모바일 40px)에 오게. 본문 #링크 · 처음 주소 · 하위 메뉴 바 · 오른쪽 목차(data-jump)
   - 스크롤 등장(.rv): 화면에 들어오면 .is-in. 움직임 줄이기면 바로 보임
   - 오른쪽 플로팅 목차(.sec-float): 화면 40% 지점을 지난 마지막 섹션을 표시, 누르면 그 섹션으로
   - 모집 프로세스(#procFlow): 화면에 보이는 동안 3.2초마다 다음 단계. 마우스 · 초점이 올라가면 그 단계에서 멈춤
   - 스스로 체크: 고른 개수 · 막대 · 하나라도 고르면 '모집 프로세스 보러 가기'
   - 자주 묻는 질문: 분류 탭 · 5개씩 페이지 · 하나씩 펼치기. 목록 높이를 질문 5개 높이로 고정해 분류를 바꿔도 아래가 안 움직임
   ========================================================= */
(() => {
  const main = document.querySelector('.check-page');
  if (!main) return;
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const root = document.documentElement;
  const header = $('#siteHeader');

  /* ---------- 위치 이동 ---------- */
  // instant: 처음 열 때처럼 바로(공통 base.css의 html scroll-behavior:smooth를 잠시 끔)
  function scrollToY(y, instant){
    if (instant || reduce) {
      const prev = root.style.scrollBehavior;
      root.style.scrollBehavior = 'auto';
      window.scrollTo(0, y);
      root.style.scrollBehavior = prev;
    } else window.scrollTo({ top: y, behavior: 'smooth' });
  }
  // 등장 전(.rv) 요소는 아래로 18px 내려가 있으므로 그만큼 빼고 잼
  function layoutTop(el){
    const t = getComputedStyle(el).transform;
    const ty = t && t !== 'none' ? new DOMMatrixReadOnly(t).m42 : 0;
    return el.getBoundingClientRect().top - ty + window.scrollY;
  }
  function jumpTo(el, instant){
    if (!el) return;
    let y = 0;
    if (el.id !== 'overview') {
      const pick = el.matches('.v3-sec') ? ($('.k-head, .s-head', el) || el) : el;   // 섹션은 머리(.k-head) 기준
      y = layoutTop(pick) - ((header ? header.offsetHeight : 0) + (matchMedia('(max-width:760px)').matches ? 40 : 64));   // 10-13: 바 ↔ 제목 여백 통일(전에는 32px)   // 헤더 높이에 하위 메뉴 바 포함
    }
    scrollToY(Math.max(0, Math.round(y)), instant);
    // 접근성: 이동한 섹션 제목으로 초점
    const h = el.querySelector('h1, h2');
    if (h) { h.setAttribute('tabindex', '-1'); h.focus({ preventScroll: true }); }
  }
  const targetOf = hash => {
    const id = hash && hash.length > 1 ? decodeURIComponent(hash.slice(1)) : '';
    const el = id && document.getElementById(id);
    return el && main.contains(el) ? el : null;
  };

  // 본문 안 같은 페이지 #링크(모집 프로세스 보러 가기 · 자주 묻는 질문 답의 링크). 연결처 미정(data-toast · data-site-link)은 공통 site.js가 안내
  main.addEventListener('click', e => {
    const a = e.target.closest('a[href^="#"]');
    if (!a || a.hasAttribute('data-toast') || e.defaultPrevented) return;
    const el = targetOf(a.getAttribute('href'));
    if (!el) return;
    e.preventDefault();
    history.replaceState(null, '', a.getAttribute('href'));
    jumpTo(el);
  });
  // 헤더 드롭다운 · 하위 메뉴 바 · 모바일 메뉴 · 푸터에서 이 페이지의 #위치를 고르면 site.js가 주소를 바꾸고(→ hashchange) 브라우저가 스크롤함.
  // 같은 위치를 다시 고를 때(주소가 그대로라 hashchange 없음)도 같은 자리로 오게 site.js 다음에 맞춤
  document.addEventListener('click', e => {
    const a = e.target.closest('#siteHeader a[href], #drawer a[href], #siteFooter a[href]');
    if (!a || !e.defaultPrevented || a.hasAttribute('data-toast')) return;   // site.js가 같은 페이지 링크만 막음
    const el = targetOf(new URL(a.href).hash);
    if (el) jumpTo(el);
  });
  addEventListener('hashchange', () => { const el = targetOf(location.hash); if (el) jumpTo(el); });

  // 처음 주소에 #위치가 있으면 그 자리로. 글꼴 · 레이아웃이 자리 잡은 뒤에도 한 번 더(그 사이 사용자가 스크롤하면 그대로 둠)
  const first = targetOf(location.hash);
  if (first) {
    let moved = false;
    const stop = () => { moved = true; };
    ['wheel', 'touchstart', 'keydown', 'pointerdown'].forEach(t => addEventListener(t, stop, { once: true, passive: true }));
    jumpTo(first, true);
    const again = () => { if (!moved) jumpTo(first, true); };
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(again);
    if (document.readyState === 'complete') again(); else addEventListener('load', again, { once: true });
  }

  /* ---------- 스크롤 등장 ---------- */
  const rvs = $$('.rv', main);
  if (reduce || !('IntersectionObserver' in window)) rvs.forEach(e => e.classList.add('is-in'));
  else {
    // 숨김(opacity 0)을 전환 없이(.rv-init) 먼저 확정한 뒤 다음 프레임에 전환을 켜고 관찰.
    // 그냥 .rv-ready만 붙이면 1 → 0 전환이 시작되자마자 is-in이 되돌려 첫 화면 요소가 떠오르지 않음
    main.classList.add('rv-ready', 'rv-init');
    void main.offsetHeight;
    requestAnimationFrame(() => {
      main.classList.remove('rv-init');
      const io = new IntersectionObserver(es => es.forEach(e => {
        if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); }
      }), { rootMargin: '0px 0px -8% 0px', threshold: .08 });
      rvs.forEach(e => io.observe(e));
    });
  }

  /* ---------- 오른쪽 플로팅 목차 ---------- */
  const sf = $('.sec-float', main);
  if (sf) {
    const btns = $$('.sf-btn', sf), secs = btns.map(b => document.getElementById(b.dataset.jump));
    const set = id => btns.forEach(b => { const on = b.dataset.jump === id; b.classList.toggle('is-active', on); if (on) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current'); });
    let raf;
    const calc = () => {
      const line = innerHeight * .4; let id = btns[0].dataset.jump;
      secs.forEach((el, k) => { if (el && el.getBoundingClientRect().top <= line) id = btns[k].dataset.jump; });
      if (innerHeight + scrollY >= document.documentElement.scrollHeight - 4) id = btns[btns.length - 1].dataset.jump;
      set(id);
    };
    const onS = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(calc); };
    addEventListener('scroll', onS, { passive: true }); addEventListener('resize', onS);
    calc();
    requestAnimationFrame(() => sf.classList.add('is-in'));
  }
  $$('[data-jump]', main).forEach(b => b.addEventListener('click', () => {
    const el = document.getElementById(b.dataset.jump); if (!el) return;
    history.replaceState(null, '', '#' + b.dataset.jump);
    jumpTo(el);
  }));

  /* ---------- 자주 묻는 질문: 분류 · 페이지 · 펼치기 ---------- */
  const fl = $('#faqList', main);
  if (fl) {
    const items = $$('.faq-item', fl), tabs = $$('.faq-tab', main), cnt = $('#faqCount', main);
    const pager = $('#faqPager', main), pagesEl = $('#faqPages', main), fprev = $('#faqPrev', main), fnext = $('#faqNext', main);
    const PER = 8; let cat = 'all', fpage = 0;
    const apply = () => {
      let n = 0;
      items.forEach(li => { const ok = cat === 'all' || li.dataset.cat === cat; li._ok = ok; if (ok) n++; });
      const list = items.filter(li => li._ok), pages = Math.max(1, Math.ceil(list.length / PER));
      fpage = Math.min(fpage, pages - 1);
      items.forEach(li => { const k = list.indexOf(li); li.hidden = !(k >= fpage * PER && k < (fpage + 1) * PER); });
      pager.classList.toggle('is-off', pages <= 1); pager.setAttribute('aria-hidden', String(pages <= 1));
      pagesEl.innerHTML = Array.from({ length: pages }, (_, k) => `<button type="button" class="faq-pn" data-p="${k}"${k === fpage ? ' aria-current="page"' : ''} aria-label="${k + 1}페이지">${k + 1}</button>`).join('');
      fprev.disabled = fpage === 0; fnext.disabled = fpage === pages - 1;
      cnt.textContent = cat !== 'all' ? n + '개의 질문' : '';
    };
    const goPage = k => {
      fpage = k; apply();
      const top = $('.faq-tools', main).getBoundingClientRect().top;
      if (top < (header ? header.offsetHeight : 0) || top > innerHeight * .5) jumpTo($('#faq', main));
    };
    pagesEl.addEventListener('click', e => { const b = e.target.closest('.faq-pn'); if (b) goPage(+b.dataset.p); });
    fprev.addEventListener('click', () => { if (fpage > 0) goPage(fpage - 1); });
    fnext.addEventListener('click', () => goPage(fpage + 1));
    tabs.forEach(t => t.addEventListener('click', () => { cat = t.dataset.cat; fpage = 0; tabs.forEach(b => b.setAttribute('aria-pressed', String(b === t))); apply(); }));
    $$('.faq-q', fl).forEach(b => b.addEventListener('click', () => {
      const li = b.closest('.faq-item'), open = !li.classList.contains('is-open');
      if (open) items.forEach(o => { o.classList.remove('is-open'); $('.faq-q', o).setAttribute('aria-expanded', 'false'); });
      li.classList.toggle('is-open', open); b.setAttribute('aria-expanded', String(open));
    }));
    const sizeList = () => {
      items.forEach(li => li.hidden = false);
      const h = Math.max(...items.map(li => $('h3', li).offsetHeight)) + 1;
      fl.style.minHeight = (h * PER + 2) + 'px';
      apply();
    };
    sizeList();
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(sizeList);
    let rz; addEventListener('resize', () => { clearTimeout(rz); rz = setTimeout(sizeList, 150); });
  }

  /* ---------- 모집 프로세스: 단계 차례로 켜기 ---------- */
  const pf = $('#procFlow', main);
  if (pf) {
    const cols = $$('.pf-col', pf); let cur = 0, auto = 0, timer = null, inView = false, hold = false;
    const set = k => { cur = k; cols.forEach((c, i) => c.classList.toggle('is-on', i === k)); };
    const stop = () => { clearInterval(timer); timer = null; };
    const start = () => { stop(); if (!reduce && inView && !hold) timer = setInterval(() => set((cur + 1) % cols.length), 3200); };
    cols.forEach((c, i) => {
      const pick = () => { if (!hold) auto = cur; set(i); hold = true; stop(); };
      c.addEventListener('mouseenter', pick); c.addEventListener('click', pick);
      const card = $('.pf-card', c); if (card) card.addEventListener('focus', pick);
    });
    // 커서가 벗어나면 호버로 켠 단계를 바로 끄고, 자동 순환하던 단계로 되돌림
    const release = () => { if (!hold) return; hold = false; set(auto); start(); };
    pf.addEventListener('mouseleave', () => { if (pf.contains(document.activeElement)) document.activeElement.blur(); release(); });
    pf.addEventListener('focusout', e => { if (!pf.contains(e.relatedTarget)) release(); });
    new IntersectionObserver(es => es.forEach(e => { inView = e.isIntersecting; start(); }), { threshold: .3 }).observe(pf);
    set(0);
  }

  /* ---------- 스스로 체크 ---------- */
  const boxes = $$('.chk-box', main), now = $('#chkNow', main), bar = $('#chkBar', main), go = $('#chkGo', main);
  if (boxes.length) {
    const upd = () => { const n = boxes.filter(b => b.checked).length; now.textContent = n; bar.style.width = (n / boxes.length * 100) + '%'; go.hidden = n < 1; };
    boxes.forEach(b => b.addEventListener('change', upd)); upd();
  }
})();

common/css/base.css:
/* =========================================================
   기본 요소: 홈 · 카테고리 페이지(선배들의 이야기 · 인사교 라이프 · 지원 전 체크) · 앞으로 만들 페이지의 바탕
   (알아보기는 전달받은 자기 base.css를 씁니다)
   불러오는 순서: tokens.css → base.css → site.css → 페이지 CSS
   ========================================================= */
html{
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
  scroll-padding-top:calc(env(safe-area-inset-top,0px) + var(--hdr) + var(--sub) + 8px);
  scroll-behavior:smooth;
  font-synthesis-weight:none;
  -webkit-text-size-adjust:100%;
}
*,*::before,*::after{box-sizing:border-box}
/* 본문은 고정 헤더(+ 하위 메뉴 바) 아래에서 시작. 본문이 짧거나 비어도 푸터는 화면 맨 아래 */
body{margin:0;min-height:100svh;display:flex;flex-direction:column;background:var(--paper);color:var(--ink);font-family:var(--ff-sans);font-size:17px;line-height:1.75;letter-spacing:-.01em;word-break:keep-all;-webkit-font-smoothing:antialiased}
main{flex:1 0 auto;padding-top:calc(var(--hdr) + var(--sub));overflow-x:clip}
img{max-width:100%;display:block}
a{color:inherit}
button{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--primary);outline-offset:3px;border-radius:2px}
main[tabindex="-1"]:focus{outline:none}   /* 본문으로 바로가기의 도착점(본문 전체)에는 테두리를 그리지 않음 */
:is(h1,h2,h3)[tabindex="-1"]:focus{outline:none}   /* #위치로 이동한 뒤 초점을 받은 섹션 제목(site.js goTo · 페이지 스크립트)도 같음: 누르는 곳이 아니라 테두리 없이 초점만 */

@media (max-width:860px){
  body{font-size:16px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
}

common/css/lnb.css:
/* =========================================================
   왼쪽 하위 메뉴(10-13 사본, 사용자 결정 '섞어서': 한눈에 보기 허브는 넓게 · 후기 · 인터뷰 · 프로젝트 · 이모저모 페이지는 왼쪽 메뉴)
   페이지가 <html data-nav="side">면 site.js가 위쪽 바를 그리지 않고(data-subnav="off" → --sub 0) main 맨 앞에 nav.lnb#siteLnb를 그림.
   1200px 이상: 본문 왼쪽 세로 메뉴(스크롤해도 헤더 아래 붙어 있음, 낮은 창은 제목 빼고 링크만) · 미만: 본문 위 가로 알약 줄
   (1024 근처는 본문 칸이 730px까지 줄어 후기 판 · 격자가 답답해 알약 줄로. 10-13)
   셀렉터는 html[data-nav="side"] #siteLnb 아래로 묶음 — 라이프의 .life-page .lnb와 이름이 같아 섞이지 않게.
   ========================================================= */

/* 왼쪽 메뉴 공통: 본문(.stories-page) 글꼴 · 줄 간격(16px 고정)과 * 초기화를 이어받지 않게 값을 다 적음 */
html[data-nav="side"] #siteLnb{font-family:var(--ff-text);line-height:1.4;letter-spacing:-.01em}
html[data-nav="side"] #siteLnb .lnb-list{list-style:none;margin:0}
html[data-nav="side"] #siteLnb .lnb-list a{text-decoration:none;color:var(--graphite);transition:color .2s,background-color .2s,border-color .2s}
html[data-nav="side"] #siteLnb .lnb-list a:hover{color:var(--ink)}
/* 바탕: 탭 내용(.st-main)이 흰 면이라 main도 흰색 — 메뉴 칸 · 오른쪽 여백(좁은 화면은 알약 줄)만 회색으로 남지 않게 */
html[data-nav="side"] .stories-page:has(> .st-main){background:#fff}

/* ---------- 1200px 이상: 왼쪽 세로 메뉴 ----------
   본문은 헤더와 같은 정렬선(--wrap · --gutter)에서 [메뉴 | 본문] 두 칸. main 안쪽 여백으로 본문 칸을 만들어
   main(크기 기준 상자, stories.css)의 폭 = 본문 칸 → 꽉 찬 띠(100cqw · 50cqw)가 본문 칸 안에서 끝남.
   메뉴는 main 높이만큼의 왼쪽 레일(absolute) 안에서 sticky — 본문 칸을 차지하지 않고, 본문이 끝나면 같이 멈춤 */
@media (min-width:1200px){
  html[data-nav="side"]{
    --lnb-x:max(var(--gutter),calc((100% - var(--wrap)) / 2 + var(--gutter)));   /* 헤더 로고 시작선(.wrap 식). 100%는 쓰는 곳의 기준 폭 = 화면 폭 */
    --lnb-w:clamp(176px,14vw,200px);
    --lnb-gap:clamp(36px,3.4vw,48px)}
  html[data-nav="side"] main#main{position:relative;padding-left:calc(var(--lnb-x) + var(--lnb-w) + var(--lnb-gap));padding-right:var(--lnb-x)}
  html[data-nav="side"] #siteLnb{position:absolute;top:calc(var(--hdr) + var(--sub));bottom:0;left:var(--lnb-x);width:var(--lnb-w)}
  /* 첫 줄(STORIES)이 본문 첫 섹션 머리(— 후기)와 같은 높이에서 시작, 스크롤하면 헤더 아래 32px에 붙음 */
  html[data-nav="side"] #siteLnb .lnb-in{position:sticky;top:calc(var(--hdr) + 32px);margin-top:var(--lnb-top,calc(var(--sec-y-first) + 4px))}   /* 탭 내용(.st-main) 위 여백과 같은 식. 머리 여백이 다른 페이지는 main에 --lnb-top */
  html[data-nav="side"] #siteLnb .lnb-head{display:flex;flex-direction:column;gap:10px;margin:0;padding:0 0 20px}
  html[data-nav="side"] #siteLnb .lnb-title{font:700 24px/1.2 var(--ff-title);color:var(--ink);word-break:keep-all}
  html[data-nav="side"] #siteLnb .lnb-list{padding:0;border-top:2px solid var(--ink)}   /* 제목 아래 굵은 선은 목록 쪽에 — 낮은 창에서 제목을 빼도 선이 남게 */
  html[data-nav="side"] #siteLnb .lnb-list a{display:flex;align-items:center;gap:10px;padding:15px 2px;border-bottom:1px solid var(--line);font-size:16px;font-weight:500}
  /* 지금 항목: 메인 색 · 굵게 + 섹션 머리(— 후기)와 같은 짧은 선 */
  html[data-nav="side"] #siteLnb .lnb-list a[aria-current]{color:var(--primary);font-weight:700}
  html[data-nav="side"] #siteLnb .lnb-list a[aria-current]::before{content:"";flex:none;width:14px;height:2px;background:currentColor}
  html[data-nav="side"] #siteLnb .lnb-list a:focus-visible{outline:2px solid var(--primary);outline-offset:-2px;border-radius:2px}

  /* 본문 칸 안: 탭 내용(.wrap)의 최대 폭 · 좌우 여백은 main 안쪽 여백이 대신함(겹치면 본문이 두 번 들어감) */
  html[data-nav="side"] .stories-page .wrap{width:auto;max-width:none;padding-left:0;padding-right:0}
  /* 프로젝트 차콜 바탕: 원래 화면 폭(50vw)으로 퍼져 왼쪽 메뉴를 덮음 → 본문 칸 폭으로, 칸 안의 판처럼 모서리를 둥글게 */
  html[data-nav="side"] .stories-page .proj::before{left:calc(50% - 50cqw);right:calc(50% - 50cqw);border-radius:var(--r-card)}
}
/* 낮은 창(10-13 검토): 페이지 맨 끝에서 sticky 메뉴는 본문 끝(= 푸터 위)에 밀려 같이 올라감. 헤더 + 메뉴(약 340) + 푸터가 한 화면에 안 들어가면
   메뉴 윗부분(STORIES · 제목)이 고정 헤더 뒤로 들어가 잘려 보임 → 이때는 제목을 빼고 링크 사이를 줄여(한 줄 44px) 링크 목록만 붙임. 1200 미만 알약 줄과 같은 판단.
   기준 높이: 1080 넘는 폭의 푸터 293px → 72 + 340 + 293 ≈ 705 → 720 */
@media (min-width:1200px) and (max-height:719.98px){
  html[data-nav="side"] #siteLnb .lnb-head{position:absolute;visibility:hidden}   /* 흐름에서 빼고 숨김: 목록 위 선이 본문 첫 머리(— 후기)와 같은 높이에서 시작 */
  html[data-nav="side"] #siteLnb .lnb-list a{padding-top:11px;padding-bottom:11px}
}
/* 링크 목록(229)도 못 들어가는 아주 낮은 창(600 미만): 따라오지 않고 본문 맨 위에 그대로 둠.
   붙여 두면 페이지 끝에서 첫 링크가 헤더 뒤로 들어감. 이동은 헤더 메뉴로 */
@media (min-width:1200px) and (max-height:599.98px){
  html[data-nav="side"] #siteLnb .lnb-in{position:static}
}

/* ---------- 1200px 미만: 본문 위 가로 알약 줄(위쪽 하위 메뉴 바 자리) ----------
   제목은 헤더 메뉴 · 페이지 머리와 겹쳐 뺌. 줄은 화면 끝까지 스크롤, 첫 알약은 본문 정렬선(--gutter)에서 시작 */
@media (max-width:1199.98px){
  html[data-nav="side"] #siteLnb .lnb-head{display:none}
  html[data-nav="side"] #siteLnb .lnb-list{position:relative;display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:17px var(--gutter) 0;scroll-padding-inline:var(--gutter)}   /* 위 17 = 알약 모양 위 20 − 누르는 자리 여분 3 */
  html[data-nav="side"] #siteLnb .lnb-list::-webkit-scrollbar{display:none}
  html[data-nav="side"] #siteLnb .lnb-list li{flex:none}
  /* 누르는 자리(a)는 44px(10-13 검토: 38px은 터치 권장 44 미달), 보이는 알약 모양은 ::before로 38px 그대로 — 후기 칩(40px)보다 커 보이지 않게. 좌우 17 = 여백 16 + 옛 테두리 1 */
  html[data-nav="side"] #siteLnb .lnb-list a{position:relative;z-index:0;display:flex;align-items:center;height:44px;padding:0 17px;border-radius:999px;font-size:14.5px;font-weight:500;white-space:nowrap}
  html[data-nav="side"] #siteLnb .lnb-list a::before{content:"";position:absolute;inset:3px 0;z-index:-1;border:1px solid var(--line);border-radius:inherit;background:var(--surface);transition:border-color .2s}
  html[data-nav="side"] #siteLnb .lnb-list a:hover::before{border-color:var(--line-ui)}
  html[data-nav="side"] #siteLnb .lnb-list a[aria-current]{color:var(--primary);font-weight:700}
  html[data-nav="side"] #siteLnb .lnb-list a[aria-current]::before{border-color:var(--primary)}
  html[data-nav="side"] #siteLnb .lnb-list a:focus-visible{outline:none}
  html[data-nav="side"] #siteLnb .lnb-list a:focus-visible::before{outline:2px solid var(--primary);outline-offset:1px}   /* 링 바깥 끝이 a 안(3px)에 들어가 가로 스크롤 줄에 잘리지 않음 */
}

html[data-nav="side"] #siteLnb .lnb-title{font-family:var(--ff-text);font-weight:700;font-size:21px;letter-spacing:-.02em}   /* 10-13: 왼쪽 메뉴 제목 Paperlogy */

common/css/site.css:
/* =========================================================
   공통 틀: 상단 헤더(GNB · 드롭다운 · 검색) · 하위 메뉴 바 · 모바일 메뉴 · 푸터 · 플로팅 버튼 · 토스트
   마크업은 common/js/site.js가 그립니다. 페이지 CSS와 섞이지 않게 셀렉터는 틀 요소 아래로 묶었습니다.
   + 본문 공용 컴포넌트(페이지 HTML에 직접 씀): 버튼 .btn · 페이지 끝 '다음으로' 띠 .next-band · 가로 넘침 흐림 [data-scroll-fade] — 맨 아래 절
   ========================================================= */

/* 틀 요소 글자 바탕: 페이지의 base.css와 상관없이 모든 페이지에서 같은 모양 */
.site-header,.drawer,.site-footer,.floating,.toast,.skip-link{font-family:var(--ff-sans);font-size:17px;line-height:1.75;letter-spacing:-.01em;word-break:keep-all;-webkit-font-smoothing:antialiased;font-synthesis-weight:none}
:root :is(.site-header,.drawer,.site-footer,.floating) :is(a,button,input):focus-visible{outline:2px solid var(--primary);outline-offset:3px;border-radius:2px}
:root :is(.hdr-bar) :is(a,button):focus-visible{outline-color:var(--header-accent)}

.wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gutter)}
.skip-link{position:fixed;top:-80px;left:16px;z-index:100;padding:12px;background:#fff;color:#14233F;text-decoration:none}
.skip-link:focus{top:10px}

/* =========================================================
   상단 헤더 / GNB — 모든 페이지 같은 어두운 막대
   ========================================================= */
.site-header{position:fixed;inset:0 0 auto 0;z-index:50;padding-top:env(safe-area-inset-top,0px);color:var(--ink);
  --logo-w:187px;                                      /* 로고(심볼 + 이름 + 광주) 칸 폭: 글꼴이 늦게 와도 GNB가 안 움직이게 고정(Pretendard에서 실제 186.9px) */
  --gnb-x:calc(var(--logo-w) + 40px + 12px + 22px)}    /* GNB 첫 메뉴(인사교 알아보기) 글자 시작 = 정렬선 + 로고 + 칸 사이(.hdr-inner gap) + .gnb 왼쪽 여백 + 링크 안쪽 여백. 하위 메뉴 바 첫 항목도 여기 */
.site-header:empty{height:calc(env(safe-area-inset-top,0px) + var(--hdr));background:var(--header-bg)}
.site-header .hdr-bar{position:relative;z-index:2;height:var(--hdr);color:var(--on-header);transition:border-color .3s,background .3s}
.site-header.is-scrolled .hdr-bar{border-bottom-color:rgba(255,255,255,.12)}   /* 막대는 늘 어두워서 선도 어두운 면 기준(밝은 회색 선이 홈 사진 위에 튀던 것) */
.site-header .hdr-inner{height:100%;display:flex;align-items:center;gap:40px}

/* 로고: 인공지능사관학교 심볼(2026-09-29 받은 원본) + 이름 */
.logo{display:flex;align-items:center;gap:10px;color:inherit;text-decoration:none;flex-shrink:0}
.site-header .hdr-bar .logo{min-width:var(--logo-w)}
.logo-mark{width:31px;height:26px;flex:none;background:url("../assets/brand/symbol-blue.png") center/contain no-repeat}
.hdr-bar .logo-mark{background-image:url("../assets/brand/symbol-white.png")}
.logo-text{font-weight:700;font-size:17px;letter-spacing:-.03em}

.site-header .hdr-nav{display:flex;flex:1;height:100%}
.site-header .gnb{display:flex;height:100%;margin:0 auto 0 12px;padding:0;list-style:none}
.site-header .gnb>li{position:relative;height:100%}
.site-header .gnb-link{display:flex;align-items:center;height:100%;padding:0 22px;color:inherit;text-decoration:none;font-size:16px;position:relative}
.site-header .gnb-link::after{content:"";position:absolute;left:22px;right:22px;transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}   /* 어두운 막대 위에서 보이는 연파랑(진한 파랑은 대비 2 : 1로 흐렸음) */
.site-header .gnb>li:hover .gnb-link::after,.site-header .gnb>li:focus-within .gnb-link::after,.site-header .gnb-link[aria-current="page"]::after{transform:scaleX(1)}
/* 다른 메뉴를 가리키는 동안은 지금 메뉴 밑줄을 접어 밑줄이 하나만 보이게(글자색은 그대로) */
.site-header .gnb:hover>li:not(:hover)>.gnb-link[aria-current="page"]::after,.site-header .gnb:focus-within>li:not(:focus-within)>.gnb-link[aria-current="page"]::after{transform:scaleX(0)}

/* 2depth 드롭다운: 메뉴에 올리면 4개 메뉴의 하위가 한 번에 펼쳐짐(황채리 원본 규칙). 펼친 바탕은 헤더 막대와 같은 색으로 이어짐 */
.site-header .drop{position:absolute;top:100%;left:0;min-width:100%;list-style:none;margin:0;padding:22px 22px 28px;opacity:0;visibility:hidden;transform:translateY(-6px);transition:opacity .25s,transform .3s var(--ease),visibility 0s .3s}
.site-header.menu-open .drop{opacity:1;visibility:visible;transform:none;transition:opacity .25s,transform .3s var(--ease)}
.site-header .drop a{display:block;padding:6px 0;font-size:15px;text-decoration:none;white-space:nowrap;transition:color .2s,transform .25s var(--ease)}
.site-header .drop a:hover,.site-header .drop a:focus-visible{transform:translateX(3px)}
.site-header .gnb>li:hover .drop a{color:var(--on-header)}
.site-header .gnb>li:hover .drop a:hover{color:var(--header-accent)}
.site-header .drop-bg{position:absolute;left:0;right:0;top:var(--hdr);height:0;overflow:hidden;transition:height .35s var(--ease);z-index:1;box-shadow:0 18px 30px -24px rgba(20,35,63,.35)}
.site-header.menu-open .drop-bg{height:var(--drop-h,210px)}
.site-header.menu-open .hdr-bar{border-bottom-color:rgba(255,255,255,.08)}

/* 헤더 오른쪽: 검색 · 공식 홈페이지 · 지원하기 · 모바일 메뉴 버튼 */
.site-header .hdr-util{display:flex;align-items:center;gap:8px;flex-shrink:0}
.icon-btn{width:44px;height:44px;display:grid;place-items:center;border:0;background:none;color:inherit;border-radius:50%;cursor:pointer;transition:background .2s}
.icon-btn:hover{background:var(--paper-2)}
.icon-btn svg{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.7}
.site-header .menu-toggle{display:none}
.site-header .official-link{font-size:16px;font-weight:700;text-decoration:none;margin-right:12px} /* 다른 메뉴(gnb-link)와 같은 글씨(10-13) */
.site-header .official-link:hover{color:var(--on-header);text-decoration:underline}
.site-header .btn-apply{display:inline-flex;align-items:center;height:40px;padding:0 18px;border-radius:40px;font-size:15px;text-decoration:none;}

/* 검색 패널: 헤더 막대 바로 아래로 펼침. 바탕은 드롭다운처럼 헤더 막대 색으로 이어짐(페이지마다 다름) */

/* =========================================================
   하위 메뉴 바(2depth): 카테고리 페이지 헤더 아래 세부 카테고리 가로 탭
   지금 항목은 site.js가 a.is-active · aria-current로 표시하고 밑줄(.subnav-indicator)을 옮김
   ========================================================= */
.site-header .subnav{position:relative;z-index:1;height:var(--sub);background:color-mix(in srgb,var(--paper) 92%,transparent);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.site-header .subnav-inner{height:100%;display:flex;align-items:center;gap:28px}
.site-header .subnav-title{font-size:16px;font-weight:500;color:var(--graphite);white-space:nowrap;border-right:1px solid var(--line);line-height:1.2}
.site-header .subnav-list{position:relative;display:flex;gap:4px;height:100%;list-style:none;margin:0;padding:0;overflow-x:auto;scrollbar-width:none}
.site-header .subnav-list::-webkit-scrollbar{display:none}
.site-header .subnav-list a{display:flex;align-items:center;height:100%;padding:0 14px;font-size:15px;color:var(--graphite);text-decoration:none;white-space:nowrap;transition:color .2s}
.site-header .subnav-list a:hover{color:var(--ink)}
.site-header .subnav-list a.is-active{color:var(--ink);font-weight:600}
.site-header .subnav-indicator{position:absolute;left:0;bottom:0;height:2px;background:var(--ink);transition:transform .4s var(--ease),width .4s var(--ease);pointer-events:none}
@media (min-width:861px){
  /* 2뎁스 시작점(2026-10-08 사용자 "모든 카테고리의 2depth 지점도 동일하게"): 첫 항목 글자 = GNB 첫 메뉴 '인사교 알아보기' 글자 아래(--gnb-x).
     왼쪽 제목(이야기 · 체크)은 고정 폭 칸이라 구분선도 모든 페이지 같은 자리, 제목 없는 바(알아보기 · 라이프)는 그만큼 띄움. 링크 안쪽 여백 14px · 칸 사이 28px 뺌 */
  .site-header .subnav-title{flex:none;width:calc(var(--gnb-x) - 28px - 14px);overflow:hidden;text-overflow:ellipsis}
  .site-header .subnav-inner>.subnav-list:first-child{margin-left:calc(var(--gnb-x) - 14px)}
}

/* =========================================================
   푸터
   ========================================================= */
.site-footer{padding:64px 0 calc(48px + env(safe-area-inset-bottom,0px));border-top:1px solid var(--line);background:var(--paper);font-size:14.5px;color:var(--graphite)}
/* 공식 교육플랫폼 푸터처럼: 위 줄 로고 · 링크, 연락처 두 줄(| 로 구분, 1080px 이하는 한 줄씩), 저작권 */
.site-footer .footer-top{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:14px 40px;margin-bottom:20px}
.site-footer address{font-style:normal;line-height:1.9}
.site-footer address ul{display:flex;flex-wrap:wrap;list-style:none;margin:0;padding:0}
.site-footer address li+li::before{content:"";display:inline-block;width:1px;height:.75em;background:currentColor;opacity:.35;margin:0 12px;vertical-align:-.04em}
.site-footer address a{text-decoration:underline;text-underline-offset:3px}
.site-footer address a:hover{text-decoration-thickness:2px}
.site-footer .footer-links{display:flex;flex-wrap:wrap;gap:8px 22px;list-style:none;margin:0;padding:0}
.site-footer .footer-links a{text-decoration:none;color:var(--ink);font-weight:500}
.site-footer .footer-links a:hover{color:var(--primary)}
.site-footer .footer-copy{margin:12px 0 1em;font-size:13px}

/* =========================================================
   플로팅 버튼(FAB): 맨 위로 — 모든 페이지 오른쪽 아래(지원하기는 헤더 · 모바일 메뉴에) · 안내 토스트
   ========================================================= */
.floating{position:fixed;right:max(20px,env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));z-index:40;display:flex;flex-direction:column;gap:10px;align-items:flex-end}
.floating .fab-top{width:48px;height:48px;border-radius:50%;border:1px solid var(--line);background:var(--surface);display:grid;place-items:center;cursor:pointer;opacity:0;visibility:hidden;pointer-events:none;transform:translateY(8px);transition:opacity .3s,transform .3s var(--ease),visibility 0s .3s}
.floating .fab-top.is-visible{opacity:1;visibility:visible;pointer-events:auto;transform:none;transition:opacity .3s,transform .3s var(--ease)}   /* 숨은 동안은 Tab으로도 안 잡힘 */
.floating .fab-top svg{width:18px;height:18px;stroke:var(--ink);fill:none;stroke-width:1.8}

.toast{position:fixed;left:50%;bottom:calc(96px + env(safe-area-inset-bottom,0px));transform:translate(-50%,12px);background:var(--ink);color:var(--paper);padding:12px 18px;border-radius:8px;font-size:14.5px;opacity:0;pointer-events:none;transition:opacity .3s,transform .3s var(--ease);z-index:90;max-width:calc(100vw - 40px)}
.toast.is-on{opacity:1;transform:translate(-50%,0)}

/* =========================================================
   모바일 메뉴(1080px 이하)
   ========================================================= */
.drawer{position:fixed;inset:0;z-index:60;background:var(--paper);color:var(--ink);padding:calc(env(safe-area-inset-top,0px) + 12px) var(--gutter) calc(env(safe-area-inset-bottom,0px) + 100px);overflow-y:auto;transform:translateX(100%);transition:transform .45s var(--ease),visibility 0s .45s;visibility:hidden}
.drawer.is-open{transform:none;visibility:visible;transition:transform .45s var(--ease)}   /* 닫을 때도 밀려 나간 뒤 숨김 */
.drawer .drawer-top{display:flex;justify-content:space-between;align-items:center;height:48px;margin-bottom:24px}
.drawer .drawer-acc{border-top:1px solid var(--line)}
.drawer .drawer-acc:last-of-type{border-bottom:1px solid var(--line)}
.drawer .acc-btn{width:100%;display:flex;justify-content:space-between;align-items:center;background:none;border:0;padding:20px 0;font-size:21px;font-weight:700;letter-spacing:-.03em;cursor:pointer;text-align:left;color:inherit}
.drawer .acc-btn svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;transition:transform .3s}
.drawer .acc-btn[aria-expanded="true"] svg{transform:rotate(180deg)}
.drawer .acc-panel{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s var(--ease)}
.drawer .acc-panel>div{overflow:hidden;visibility:hidden;transition:visibility 0s .35s}   /* 접힌 목록의 링크는 Tab으로 안 잡힘 */
.drawer .acc-btn[aria-expanded="true"] + .acc-panel{grid-template-rows:1fr}
.drawer .acc-btn[aria-expanded="true"] + .acc-panel>div{visibility:inherit;transition:none}   /* inherit: 메뉴가 닫히면(.drawer 숨김) 펼친 목록 링크도 같이 숨음 */
.drawer .acc-panel a{display:block;padding:9px 0;color:var(--graphite);text-decoration:none;font-size:16.5px}
/* 지금 위치: 지금 카테고리 이름은 메인 색, 지금 세부 항목은 하위 메뉴 바처럼 잉크 · 굵게 · 밑줄(site.js가 aria-current) */
.drawer .acc-btn.is-current{color:var(--primary)}
.drawer .acc-panel a[aria-current]{color:var(--ink);font-weight:600;text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:7px}
.drawer .acc-panel a:last-child{margin-bottom:18px}
.drawer .drawer-cta{position:fixed;left:var(--gutter);right:var(--gutter);bottom:calc(20px + env(safe-area-inset-bottom,0px));display:flex;justify-content:center;height:54px;align-items:center;border-radius:54px;background:var(--cta);color:var(--on-cta);font-weight:700;text-decoration:none;border:2px solid var(--ink-strong);box-shadow:3px 3px 0 var(--ink-strong)}   /* 10-14: 노랑 → 헤더와 같은 흰 알약 */

/* =========================================================
   반응형
   ========================================================= */
@media (max-width:1180px){
  .site-header .official-link{display:none}   /* 메뉴 글자가 두 줄로 꺾이지 않게. 공식 홈페이지는 푸터에도 있음 */
}
@media (max-width:1080px){
  .site-header .hdr-nav,.site-header .drop-bg,.site-header .btn-apply{display:none}   /* 메뉴 칸째 숨김: 빈 칸이 남으면 간격이 두 번 들어가 375px 이하에서 ☰가 화면 밖으로 밀림 */
  .site-header .menu-toggle{display:grid}
  .site-header .hdr-inner{justify-content:space-between;gap:12px}
  .site-footer address ul{display:block}
  .site-footer address li+li::before{display:none}
}
@media (max-width:860px){
  .site-header,.drawer,.floating{font-size:16px}
  .site-header .subnav-title{display:none}
  .site-header .subnav-list{margin:0 calc(var(--gutter) * -1);padding:0 calc(var(--gutter) - 12px)}   /* 첫 탭 글자가 로고 · 히어로 제목과 같은 선(링크 좌우 여백 12px만큼 뺌) */
  .site-header .subnav-list a{padding:0 12px;font-size:14.5px}
  .floating{right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px))}
}

/* =========================================================
   본문 공용 컴포넌트 — 페이지 HTML에 직접 쓰는 조각(2026-10-08, 세 카테고리 페이지가 한 사이트로 보이게)
   글꼴은 페이지 본문 글꼴을 이어받음(카테고리 페이지는 --ff-text "Paperlogy"), 큰 글자만 --ff-title
   ========================================================= */

/* ---------- 버튼: 세 가지 + 작은 크기 ----------
   <a class="btn" href="…">주 버튼</a>                         잉크로 채운 알약(높이 48)
   <a class="btn is-line" href="…">보조 버튼</a>               흰 바탕 + 선
   <a class="btn is-cta" href="#apply" data-site-link="apply">지원하기</a>   흰 알약(헤더 지원하기와 같음, 10-14)
   작은 크기는 is-sm(높이 40). 아이콘은 <svg aria-hidden="true"> 앞이나 뒤에(18px, 선 currentColor). <button class="btn" type="button">도 같음
   :root를 붙인 까닭: 페이지 CSS의 요소 초기화(.life-page a{color:inherit} · .life-page button{font:inherit})보다 앞서게. 페이지에서 바꿀 땐 .페이지 .btn.이름 */
:root .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:48px;padding:0 24px;border:1px solid var(--ink);border-radius:999px;background:var(--ink);color:#fff;font:inherit;font-size:15.5px;font-weight:600;line-height:1;letter-spacing:-.01em;text-decoration:none;white-space:nowrap;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
:root .btn:hover{background:color-mix(in srgb,var(--ink) 84%,#fff);border-color:color-mix(in srgb,var(--ink) 84%,#fff)}
:root .btn.is-line{background:var(--surface);border-color:var(--line);color:var(--ink)}
:root .btn.is-line:hover{border-color:var(--ink)}
/* 10-14: 헤더 지원하기와 같은 흰 알약 */
/* 카카오톡 문의: 카카오 브랜드 노랑(값은 --cta와 같지만 브랜드 색이라 따로, 2026-10-08 사용자 결정으로 되살림) */
:root .btn.is-sm{height:40px;padding:0 18px;font-size:14.5px;gap:6px}
:root .btn svg{width:18px;height:18px;flex:none;stroke:currentColor;fill:none;stroke-width:1.8}
:root .btn.is-sm svg{width:16px;height:16px}
:root .btn:is(:disabled,[aria-disabled="true"]){opacity:.45;pointer-events:none}
:root .btn:focus-visible{border-radius:999px}   /* base.css의 초점 테두리 모서리(2px) 대신 알약 그대로 */

/* ---------- 페이지 끝 '다음으로' 띠: 어두운 '다음으로' 카드 하나 + 밝은 '함께 보면 좋은' 카드 둘, 푸터 바로 위 ----------
   <nav class="next-band" aria-label="다음으로 볼 페이지"><div class="wrap">
     <a href="…"><small>다음으로</small><b>제목</b><span>한 줄 설명</span></a>
     <a href="…"><small>함께 보면 좋은</small><b>제목</b><span>한 줄 설명</span></a>
     <a href="…"><small>함께 보면 좋은</small><b>제목</b><span>한 줄 설명</span></a>
   </div></nav>
   어두운 카드의 작은 글 · 화살표 색은 --next-accent(없으면 헤더 연파랑). 페이지 CSS에서 카테고리 색으로: .life-page{--next-accent:#6FC3D1}
   지원하기처럼 강조: 첫 카드에 class="is-cta"(작은 글 · 화살표가 --primary)
   세로 여백(2026-10-08): 띠 앞 마지막 내용 ↔ 첫 카드가 섹션 사이와 같은 --sec-y 한 번. 바탕이 바뀌는 경계(띠 위 선)의 양쪽에 반씩 —
   띠 바로 앞 형제(섹션 · 안내문 등, 페이지 CSS와 상관없이)의 아래 여백 --sec-y / 2 + 띠 위 여백 --sec-y / 2. 띠 아래도 --sec-y / 2(푸터 위 선 너머 푸터 위 여백 64px).
   전에는 둘 다 --sec-y여서 1440에서 마지막 내용 ↔ 카드가 225px(섹션 사이 112px의 두 배)
   main 맨 끝에 두면 main 아래 여백은 0. :root는 버튼과 같은 까닭 */
/* 화살표: 원(::before) + 화살(::after, 색을 칠하는 그림 틀) */
/* 첫 카드: 어두운 '다음으로' */
@media (max-width:860px){
  /* 한 줄씩: 화살표는 오른쪽 가운데 */
}

/* ---------- 구분점(·) 목록: 줄이 바뀌는 자리의 점은 감춤(2026-10-08) ----------
   줄 끝에 '탑승 ·'처럼 점만 남지 않게. <span class="seps"><span><span>항목</span><span>항목</span></span></span>
   바깥이 자르고(overflow), 안쪽 줄을 점 칸만큼 왼쪽으로 당겨 줄 첫 항목 앞의 점이 바깥 밖으로 나가게. 항목은 통째로 다음 줄로
   (한 항목이 줄보다 길면 그 안에서 줄바꿈 · 둘째 줄은 점 칸만큼 내어쓰기). 쓰는 곳: 인사교 라이프 오시는 길 단계 · '다음으로' 띠 카드 설명
   margin을 다시 정하는 것은 띠의 span 규칙(margin-top 8px)이 안쪽 span에 번지지 않게. 자르기는 가로만(clip) — 사진 위 글의 그림자가 위아래로 잘리지 않게 */
/* 점 칸 폭 = 글 ' · '(띄어쓰기 · 점 · 띄어쓰기)의 실제 폭(Paperlogy Text 0.72em) — 점 간격이 손으로 쓴 ' · '와 같게 */
/* 첫 점은 늘 잘려 안 보임 — 화면 읽기에서도 빼기(링크 이름이 '제목 · 첫 항목'이 되지 않게) */

/* ---------- 가로로 넘치는 탭 줄: 더 있으면 끝을 흐리게 ----------
   공통 하위 메뉴 바는 자동. 페이지의 가로 스크롤 줄은 그 요소에 data-scroll-fade(예: <div class="wrap" data-scroll-fade>)
   site.js가 넘칠 때만 .fade-l(왼쪽에 더 있음) · .fade-r(오른쪽에 더 있음)을 붙임 */
:is(.subnav-list,[data-scroll-fade]).fade-r{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 40px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 40px),transparent)}
:is(.subnav-list,[data-scroll-fade]).fade-l{-webkit-mask-image:linear-gradient(90deg,transparent,#000 40px);mask-image:linear-gradient(90deg,transparent,#000 40px)}
:is(.subnav-list,[data-scroll-fade]).fade-l.fade-r{-webkit-mask-image:linear-gradient(90deg,transparent,#000 40px,#000 calc(100% - 40px),transparent);mask-image:linear-gradient(90deg,transparent,#000 40px,#000 calc(100% - 40px),transparent)}

/* ---------- 디자인통일v1(10-12): 상단 메뉴를 랜딩 헤더와 같게 ---------- */
/* 10-13: 새 랜딩(aica-home-v2 home.css 'v2.1 GNB')과 같은 헤더 — 파랑 막대 · 흰 굵은 메뉴 · 아래 검정 3px 선 · 흰 지원하기(검정 테두리 + 그림자) */
.site-header .gnb-link{font-weight:700}
.site-header .gnb-link::after{height:3px;bottom:-3px;background:#fff}
.site-header .gnb-link:hover,
.site-header .gnb-link:focus-visible,
.site-header .gnb-link[aria-current="page"]{color:#fff}
.site-header .hdr-bar,.site-header.is-scrolled .hdr-bar,.site-header.menu-open .hdr-bar{border-bottom:3px solid var(--ink-strong)}
.site-header.menu-open .drop-bg{border-bottom:3px solid var(--ink-strong)}
.site-header .drop a{font-weight:500;color:#fff}
.site-header .drop a:hover,.site-header .drop a:focus-visible{color:#fff;text-decoration:underline;text-underline-offset:4px}
.site-header .official-link{color:#fff;opacity:1}
.hdr-bar .icon-btn:hover{background:rgba(11,11,12,.18)}
.site-header .btn-apply{background:#fff;color:var(--header-bg);font-weight:700;border:2px solid var(--ink-strong);box-shadow:3px 3px 0 var(--ink-strong);transition:transform .2s var(--ease),box-shadow .2s var(--ease)}
.site-header .btn-apply:hover{background:#fff;transform:translate(-2px,-2px);box-shadow:5px 5px 0 var(--ink-strong)}
:root .site-header :is(a,button,input):focus-visible{outline-color:#fff}
@media (max-width:860px){.site-header .btn-apply{box-shadow:2px 2px 0 var(--ink-strong)}}
/* 바탕: 밝은 페이지에서도 랜딩과 같은 색이 되도록 불투명하게 */
.site-header .hdr-bar,
.site-header .drop-bg{background:var(--header-bg);-webkit-backdrop-filter:none;backdrop-filter:none}
/* 로고 크기 · 간격: 랜딩과 같게(심볼 34×29, 간격 11px) */
.site-header .logo{gap:11px}
.site-header .logo-mark{width:34px;height:29px}

/* 디자인통일v1(10-12): 하위 메뉴 바 왼쪽 페이지 이름(선배들의 이야기 · 인사교 LIFE · 지원 전 Check)을 오른쪽 정렬해 세로 구분선에 붙임 */
.site-header .subnav-title{text-align:right}
/* 이름 ↔ 구분선 여백을 구분선 ↔ 첫 메뉴 글자 여백(바 사이 간격 28px + 메뉴 왼쪽 안쪽 여백 14px = 42px)과 같게. 메뉴 위치는 그대로 */
.site-header .subnav-title{padding-right:41px}   /* 구분선 1px 포함 42px */

/* 헤더 · 모바일 메뉴 버튼 = '문의하기' + 카카오톡 말풍선(10-14, 지원하기 대신). 모양은 흰 알약 그대로, 말풍선만 카카오 검정 */
.site-header .btn-ask,.drawer .drawer-cta{gap:7px}
.site-header .btn-ask .ic-kakao{width:18px;height:18px;flex:none;fill:#191919}
.drawer .drawer-cta .ic-kakao{width:20px;height:20px;flex:none;fill:#191919}

common/css/tokens.css:
/* =========================================================
   사이트 토큰: 메인 색 · 글꼴 · 크기 (모든 페이지 공통)
   색 · 글꼴을 바꿀 때는 이 파일만 고칩니다.
   2026-10-06 결정: 메인 색 #2457F5, 지원하기 버튼 노랑 #FEE500, 랜딩 바탕 · 헤더 막대 기본색 차콜 #2B2D31(10-07 변경, 전에는 파랑 #0B2854), 기본 글꼴 Pretendard(알아보기 글꼴), 작은 제목 Paperlogy, 큰 제목 Giants
   ========================================================= */

/* 글꼴 파일은 common/assets/fonts. Pretendard는 400 · 700 · 900 파일만 있어 500 이하는 Regular, 600~800은 Bold로 씁니다 */
@font-face{font-family:"Pretendard";src:url("../assets/fonts/Pretendard-Regular.woff2") format("woff2");font-weight:100 500;font-style:normal;font-display:swap}
@font-face{font-family:"Pretendard";src:url("../assets/fonts/Pretendard-Bold.woff2") format("woff2");font-weight:600 800;font-style:normal;font-display:swap}
@font-face{font-family:"Pretendard";src:url("../assets/fonts/Pretendard-Black.woff2") format("woff2");font-weight:900;font-style:normal;font-display:swap}
@font-face{font-family:"Giants";src:url("../assets/fonts/Giants-Bold.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap}
/* Paperlogy 한 가족(2026-10-13 정리): 전에는 Paperlogy · Paperlogy Text · Paperlogy Title · Paperlogy XB · School Paperlogy 다섯 이름.
   굵기 → 파일: 400 Regular · 500 Medium · 600 SemiBold(700도 여기) · 800 ExtraBold · 900 Black. 7 Bold 파일은 없음 */
@font-face{font-family:"Paperlogy";src:url("../assets/fonts/Paperlogy-4Regular.woff2") format("woff2");font-weight:100 449;font-style:normal;font-display:swap}
@font-face{font-family:"Paperlogy";src:url("../assets/fonts/Paperlogy-5Medium.woff2") format("woff2");font-weight:450 549;font-style:normal;font-display:swap}
@font-face{font-family:"Paperlogy";src:url("../assets/fonts/Paperlogy-6SemiBold.woff2") format("woff2");font-weight:550 749;font-style:normal;font-display:swap}
@font-face{font-family:"Paperlogy";src:url("../assets/fonts/Paperlogy-8ExtraBold.woff2") format("woff2");font-weight:750 849;font-style:normal;font-display:swap}
@font-face{font-family:"Paperlogy";src:url("../assets/fonts/Paperlogy-9Black.woff2") format("woff2");font-weight:850 900;font-style:normal;font-display:swap}

:root{
  /* 색 */
  --primary-deep:#102D80;  /* 남색. 쓰는 곳: 기수별 인스타 모양. 10-14: 디자인시스템(AI-Log) 이름에 맞춰 --blue* → --primary*로 바꿈(홈 자체 변수는 --hm-primary*) */
  --primary:#2457F5;        /* 메인 색: 버튼 · 강조 · 링크. 10-13: 헤더(프라이머리)와 같은 색으로 통일(전에는 #1F4ED8) */
  --primary-soft:#DCE5F7;
  --ink:#14233F;         /* 본문 · 제목 */
  --ink-strong:#0B0B0C;  /* 스티커 말투의 굵은 선 · 번짐 없는 그림자(배너 · 모서리 탭) */
  --graphite:#566175;    /* 보조 글: 흰 바탕 6.5 : 1 */
  --muted:#666F81;       /* 캡션 · 덜 중요한 글: 흰 바탕 5.1 : 1 · paper 4.7 : 1(작은 글도 AA) */
  --line:#D3D9E1;
  --line-ui:color-mix(in srgb,var(--ink) 55%,var(--surface));   /* 입력 칸 · 고르는 칩 · 진행 막대처럼 경계가 곧 모양인 UI의 선: 바탕(--paper) 3.4 : 1 · 흰 면 3.7 : 1(--line 1.3 : 1은 장식 선 · 카드 테두리용) */
  --paper:#F5F7F6;       /* 바탕 */
  --paper-2:#E9EEF3;
  --surface:#FFFFFF;
  --cta:#FFFFFF;         /* 지원하기 버튼(10-14 결정: 흰 알약 + --ink-strong 2px 테두리 + 번짐 없는 그림자 + 파란 글자). 헤더 · 모바일 메뉴 · .btn.is-cta */
  --on-cta:#2457F5;      /* 흰 알약 위 글자: 메인 파랑. 다크 모드에서도 이 값 고정(흰 면 위 5.6 : 1) */
  --yellow:#FEE500;      /* 강조 노랑(10-14: 전 --cta 값). 선배들의 이야기 장식(번호 · 키커 · 배지 · 분류 점) · 카카오톡 버튼. 지원하기에는 쓰지 않음 */

  /* 상단 헤더 막대. 기본은 랜딩 바탕색(home.css --ax-bg가 이 값을 씀): 차콜
     페이지마다 자기 CSS에서 :root{--header-bg:…}로 그 페이지에 맞는 색을 씀(알아보기 #1C2A4A) */
  --header-bg:#2457F5;   /* 10-13: 새 랜딩(aica-home-v2) 헤더와 같은 파랑. 흰 글자 5.6 : 1. 전에는 남색 #102D80 */
  --on-header:#fff;
  --header-muted:#fff;   /* 파랑 위 흐린 흰색은 대비 미달이라 쓰지 않음(랜딩과 같음) */
  --header-accent:#fff;  /* 현재 메뉴 · 포커스: 흰 글자 + 흰 밑줄 */

  /* 글꼴 */
  --ff-sans:"Pretendard","Apple SD Gothic Neo","Malgun Gothic",system-ui,sans-serif;   /* 기본: 본문 · 메뉴 · 푸터 */
  --ff-sub:"Paperlogy","Pretendard",sans-serif;    /* 작은 제목(지금은 board.css만 씀. 알아보기는 자기 'Paperlogy') */
  --ff-title:"Giants","Pretendard",sans-serif;     /* 큰 제목 */
  --ff-text:"Paperlogy","Pretendard","Apple SD Gothic Neo","Malgun Gothic",system-ui,sans-serif;   /* 카테고리 페이지 본문(이야기 · 라이프 · 체크 같게, 2026-10-08) */

  /* 크기 */
  --hdr:72px;            /* 상단 헤더 높이 */
  --sub:0px;             /* 하위 메뉴 바 높이: 바가 있는 카테고리 페이지만 아래 규칙으로 52px */
  --wrap:1376px;   /* 10-13: 내용 폭 1280px(+ 좌우 여백 48px씩) — 전에는 1240px(내용 1144px) */
  --gutter:clamp(20px,4vw,48px);
  /* 카테고리 페이지 세로 리듬(2026-10-07, 지원 전 체크 시안 값을 사이트 기준으로). 가로 정렬은 위 --wrap · --gutter(헤더와 같은 선) */
