.school-about .section-navigation{display:none!important}
.school-about .sec-float{position:fixed;right:clamp(14px,2.2vw,36px);top:50%;z-index:30;transform:translateY(-50%);opacity:0;transition:opacity .4s var(--ease,cubic-bezier(.22,.61,.36,1))}
