.school-about .sec-float ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;align-items:center;gap:18px}
.school-about .sf-btn{display:flex;flex-direction:column;align-items:center;gap:0;padding:6px 8px;background:none;border:0;cursor:pointer;font:inherit;color:var(--graphite)}
.school-about .sf-slash{display:block;width:22px;height:14px;position:relative}
.school-about .sf-slash::before{content:"";position:absolute;left:50%;top:50%;width:20px;height:1.5px;border-radius:1px;background:currentColor;opacity:.55;transform:translate(-50%,-50%) rotate(-28deg);transition:opacity .25s,background .25s,width .25s var(--ease,cubic-bezier(.22,.61,.36,1))}
.school-about .sf-label{writing-mode:vertical-rl;font-size:13px;font-weight:600;letter-spacing:.08em;line-height:1;white-space:nowrap;color:var(--primary);max-height:0;opacity:0;overflow:hidden;margin-top:0;transition:max-height .45s var(--ease,cubic-bezier(.22,.61,.36,1)),opacity .3s,margin-top .3s var(--ease,cubic-bezier(.22,.61,.36,1))}
.school-about .sf-btn::after{content:"";display:block;width:1px;height:0;margin-top:0;background:var(--primary);transition:height .45s var(--ease,cubic-bezier(.22,.61,.36,1)),margin-top .45s var(--ease,cubic-bezier(.22,.61,.36,1))}
.school-about .sf-btn:hover .sf-label,:where(html:not([data-menu="stories"])) .sf-btn:focus-visible .sf-label{max-height:220px;opacity:1;margin-top:10px}
.school-about .sf-btn:hover::after,:where(html:not([data-menu="stories"])) .sf-btn:focus-visible::after{height:64px;margin-top:12px}
.school-about .sf-btn:hover .sf-slash::before,:where(html:not([data-menu="stories"])) .sf-btn:focus-visible .sf-slash::before{opacity:1;background:var(--primary);width:24px}
.school-about .sf-btn.is-active .sf-slash::before{opacity:1;background:var(--primary);width:24px}
.school-about .sf-btn:focus-visible{outline:2px solid var(--primary);outline-offset:2px;border-radius:4px}
@media (max-width:767px){.school-about .sec-float{display:none}}
@media (prefers-reduced-motion:reduce){.school-about .sec-float,.school-about .sf-label,.school-about .sf-btn::after,.school-about .sf-slash::before{transition:none}}
/* 알아보기 플로팅 목차: 어두운 히어로 위에서는 흰 막대 · 흰 글자 */
.school-about .sec-float.on-dark .sf-btn{color:rgba(255,255,255,.85)}
.school-about .sec-float.on-dark .sf-btn.is-active .sf-slash::before,
.school-about .sec-float.on-dark .sf-btn:hover .sf-slash::before{background:#fff}
.school-about .sec-float.on-dark .sf-label{color:#fff}
.school-about .sec-float.on-dark .sf-btn::after{background:#fff}
