  --g900:var(--ink); --g600:var(--graphite); --g300:var(--line); --g50:var(--paper);
  --pri:var(--primary);
  --l-blue:var(--primary); --l-eb:var(--primary);
  --num:var(--ff-title);   /* 숫자: Anton → Giants(체크와 같게) */
}
.stories-page .sh h2{
  font-size:clamp(28px,2.8vw,38px);
  font-weight:700;
  color:var(--ink);
}

