/* =========================================================
   글꼴 위계(2026-10-13 결정, 선배들의 이야기 기준)
   - 큰 제목(배너 · 히어로 · 큰 숫자): Giants
   - 섹션 제목 · 카드 제목 · 라벨 · 버튼 같은 짧은 글: Paperlogy 600(SemiBold). 강조 큰 카드 제목만 800
   - 두 줄 이상 본문: Pretendard
   Paperlogy를 한 가족으로 합치면서 800 · 900으로 적혀 있던 짧은 글이 더 굵어지지 않게 600으로 맞춤(전에도 화면은 SemiBold였음)
   ========================================================= */
.life-page :is(.bx9-info h4,.bx9-head h3,.hzmw-tt,.hzc-here,.wmap .ad b,.wbld figcaption b,.fsx a i,a.more,.rt3 article h3,.rt3 article ol li i),:is(.stories-page,.stories-hub) .hb-pi-c b,.school-about :is(.why-school-highlights strong,.common-courses-meta strong){font-weight:600!important}
/* 알아보기 섹션 제목: Giants → Paperlogy(표지 큰 제목은 Giants 그대로) */
.school-about #intro .intro-purpose #intro-heading,
.school-about .about-paper :is(h2,h3):not(#why-school *):not(.common-course-card h3),
.school-about #why-school-heading{font-family:var(--ff-text)!important;font-weight:600!important;letter-spacing:-.025em}
/* 두 줄 이상 본문은 Pretendard */
