/* 섹션 제목 크기 · 키커를 한 공식으로(선배들의 이야기 기준): 체크 h2 42 → 38px, 체크 키커 .k-label도 .sh-k처럼 Paperlogy 14.5px 700 */
.check-page .s-head h2{font-size:clamp(28px,2.8vw,38px)!important;line-height:1.22}
.check-page .k-label{font-family:var(--ff-text);font-size:14.5px;letter-spacing:.02em;line-height:1.3}
/* 버튼 · 입력은 글꼴을 물려받기(전에는 일부 칩 · 보기 전환 버튼이 Arial로 보였음). :where라 따로 정한 글꼴이 있으면 그쪽이 이김 */
:where(.stories-page,.stories-hub,.life-page,.check-page,.school-about) :where(button,input,select,textarea){font-family:inherit}

/* =========================================================
   후기 글 창(모달) = 포스트잇 한 장(10-13 최종)
   - 한 가지 색(카드 색 --pi) · 모서리 10px · 위 접착 띠 없음
   - 오른쪽 아래 모서리가 말려 올라감: 종이는 모서리를 잘라내고(::before), 말린 뒷면(::after)은 진한 금빛 → 접힌 쪽으로 밝게, 그 아래 옅은 그림자
   - 그림자는 종이 모양을 그대로 따라가도록 filter: drop-shadow
   - 열 때 한 번: 살짝 떠오르며 펄럭(piBend) + 처음엔 반듯이 펼쳐져 있다가 모서리가 말려 올라감(piCurl).
     잘린 자리 · 말린 뒷면 · 그림자가 같은 값(--k: 0→1)으로 함께 커져서 떨어져 보이지 않음
   ========================================================= */
@property --k{syntax:"<number>";inherits:true;initial-value:1}
.stories-page .ov .sheet{--k:1;--curl:calc(var(--k) * 64px);background:transparent;border-radius:10px;box-shadow:none;clip-path:none;overflow:visible;isolation:isolate;transform:none;transform-origin:left center;
  filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.16)) drop-shadow(0 24px 28px rgba(0,0,0,.36))}
.stories-page .ov .sheet .mscroll{border-radius:10px;padding-bottom:28px;clip-path:polygon(0 0,100% 0,100% calc(100% - var(--curl)),calc(100% - var(--curl)) 100%,0 100%)}
.stories-page .ov .sheet::before{display:block;content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:1;width:auto;border-radius:10px;
  clip-path:polygon(0 0,100% 0,100% calc(100% - var(--curl)),calc(100% - var(--curl)) 100%,0 100%);
  background:radial-gradient(ellipse max(1px,calc(var(--k) * 46px)) max(1px,calc(var(--k) * 46px)) at calc(100% - var(--k) * 30px) calc(100% - var(--k) * 30px),rgba(80,55,0,.26) 40%,rgba(80,55,0,0) 100%),var(--pi,#FFF1A6);animation:none}
.stories-page .ov .sheet::after{display:block;content:"";position:absolute;z-index:3;right:0;bottom:0;width:64px;height:64px;pointer-events:none;
  border-radius:0;filter:none;transform:scale(var(--k));transform-origin:100% 100%;
  clip-path:path("M64 0 C 46 7, 22 7, 9 7 Q 5 7, 6 12 C 7 26, 6 46, 0 64 C 22 58, 52 34, 64 0 Z");
  background:linear-gradient(315deg,color-mix(in srgb,var(--pi,#FFF1A6) 70%,#A87A10) 38%,color-mix(in srgb,var(--pi,#FFF1A6) 82%,#C9A23A) 62%,color-mix(in srgb,var(--pi,#FFF1A6) 90%,#fff) 100%)}
.stories-page .ov .x{width:40px;height:40px;right:14px;top:12px;background:transparent;box-shadow:none;color:var(--ink);font:300 30px/1 var(--ff-sans);border-radius:50%}
.stories-page .ov .x:hover{background:rgba(20,35,63,.08);color:var(--ink)}
@media (prefers-reduced-motion:no-preference){
  .stories-page .ov{perspective:1600px}
  .stories-page .ov:target .sheet{animation:piIn-st .38s cubic-bezier(.2,.8,.2,1),piBend 1.1s ease-out .1s 1,piCurl .9s cubic-bezier(.3,1.25,.5,1) .35s 1 both}
}
@keyframes piIn-st {from{transform:translateY(16px) scale(.97);opacity:0}to{transform:none;opacity:1}}
@keyframes piCurl {from{--k:0}to{--k:1}}
@keyframes piBend {0%{transform:none}22%{transform:rotateY(-2.2deg) skewY(-.3deg)}48%{transform:rotateY(.8deg)}72%{transform:rotateY(-.3deg)}100%{transform:none}}
@media (max-width:860px){.stories-page .ov .sheet{border-radius:10px}}

/* 시설 둘러보기 사진 옆 선배 포스트잇: 화면 오른쪽에서 잘리지 않게 폭을 줄이고 사진 쪽으로 당김(10-13) */
