/* =========================================================
   생활 꿀팁 = 주제별 화면(10-13, 1안)
   #tips: 네 주제 카드(.tp-hub)만 · #tp-*: 위 '← 생활 꿀팁 전체' + 주제 바로가기(.tp-bar)와 그 주제만
   ========================================================= */
body .life-page #pg-tips:not([data-topic]) :is(.tp-sec,.tp-bar,.disc){display:none}
body .life-page #pg-tips[data-topic] .tp-hub{display:none}
body .life-page #pg-tips[data-topic] .tp-sec{display:none}
body .life-page #pg-tips[data-topic="tp-house"] #tp-house,body .life-page #pg-tips[data-topic="tp-food"] #tp-food,
body .life-page #pg-tips[data-topic="tp-fun"] #tp-fun,body .life-page #pg-tips[data-topic="tp-adapt"] #tp-adapt{display:block}
body .life-page .tp-hub{padding-bottom:clamp(64px,6vw,96px)}
body .life-page .tp-hubg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:clamp(24px,2.6vw,36px)}
body .life-page .tp-hc{position:relative;display:grid;grid-template-columns:200px 1fr;gap:22px;align-items:center;padding:14px 56px 14px 14px;border-radius:24px;
  background:linear-gradient(180deg,#F3F4F8,#EEF0F4);box-shadow:inset 0 0 0 1px rgba(20,35,63,.06);color:var(--ink);text-decoration:none;transition:transform .2s,box-shadow .2s}
body .life-page .tp-hc:hover{transform:translateY(-3px);box-shadow:inset 0 0 0 1px rgba(20,35,63,.06),0 24px 40px -22px rgba(20,35,63,.4)}
