  font:600 14px/1 var(--ff-text);color:var(--graphite);text-decoration:none;white-space:nowrap}
body .life-page .tp-bar a:hover{color:var(--primary);box-shadow:inset 0 0 0 1px var(--primary)}
body .life-page .tp-bar nav{display:flex;gap:6px;flex-wrap:wrap}
