body .life-page #pg-tips[data-topic] .tp-sec{padding-top:clamp(28px,3vw,40px)}
.lnb .lnb-tp{display:flex;flex-direction:column;padding:0 0 var(--tpb,15px) 22px;border-bottom:1px solid rgb(211,217,225)} /* 위아래 여백 같게 + 아래 선(10-13) */
