.lnb .lnb-tp a.is-on{font-weight:700!important}
@media (max-width:860px){body .life-page .tp-hubg{grid-template-columns:1fr}body .life-page .tp-hc{grid-template-columns:110px 1fr;padding-right:44px}body .life-page .tp-htx b{font-size:18px}}
