/* 점심 주사위(10-13): 되돌리기는 글자 없이 동그란 × 버튼 · '오늘은 여기!'는 사진 왼쪽 아래 구석으로(음식을 가리지 않게) */
.life-page .fdc.pick .fd-unpick{width:32px;height:32px;padding:0;justify-content:center;border-radius:50%;top:10px;right:10px;box-shadow:0 2px 6px rgba(20,35,63,.18)}
