:where(html:not([data-menu="stories"])) .fdg .fdc.pick .fdc-ph::after{left:12px;top:auto;bottom:10px;padding:7px 12px;font-size:21px;transform:rotate(-9deg);transform-origin:left bottom}
.lnb .lnb-tp a::before,.lnb .lnb-tp a::after{content:none!important;display:none!important}.lnb .lnb-tp a{padding-left:0!important}
.lnb .lnb-list a:has(+ .lnb-tp){border-bottom:0!important} /* 생활 꿀팁과 그 아래 주제 사이 선 없음(10-13) */
