.check-page .cb1 .cbl::before{content:"";position:absolute;right:110px;top:-12px;width:96px;height:26px;background:#C6F56A;border:1.5px solid var(--ink-strong);transform:rotate(-3deg)}
.check-page .cb1 .cbl>p{margin:0 0 4px;font:400 15px/1 var(--ff-title);letter-spacing:.08em;color:var(--primary)}
.check-page .cb1 .cbl a{display:flex;align-items:center;gap:14px;padding:11px 2px;border-bottom:1px dashed #C9D1DE}
.check-page .cb1 .cbl a:last-child{border-bottom:0}
.check-page .cb1 .cbl .ic{flex:none;width:26px;height:26px}
