.check-page .cb1 .cbl b{font:700 16px/1.3 var(--ff-sans);letter-spacing:-.02em;color:var(--ink)} .check-page .cb1 .cbl small{font:400 13px/1.4 var(--ff-sans);color:#6B7486}
.check-page .cb1 .cbl a:hover b{color:var(--primary)}
.check-page .cb1 .ok{position:absolute;right:-18px;bottom:-14px;display:grid;place-items:center;width:58px;height:58px;border-radius:50%;background:#C6F56A;border:1.5px solid var(--ink-strong);box-shadow:3px 3px 0 var(--ink-strong)}
.check-page .cb1 .ok svg{width:28px;height:28px;fill:none;stroke:var(--ink-strong);stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round}
@media (max-width:960px){.check-page .cb1 .cbx{grid-template-columns:1fr}.check-page .cb1 .cbl{transform:rotate(1deg)}}
.check-page .ckx.cb{border-bottom:0;background:none}
.check-page .ckx.cb{padding-bottom:0}.check-page .ckx.cb>.wrap{padding-bottom:16px}
/* 먹거리 안내 문구(10-14): 카드 묶음 바로 아래 오른쪽 끝 */
body .life-page .fdisc{margin-top:14px;text-align:right}
/* 형광펜(10-14, KeyStatement와 같은 값): 정보 글에서 꼭 기억할 조건 · 결론 한 구절에만. 문단당 1곳 */
.check-page mark.hl{background:linear-gradient(transparent 58%,#DCE5FF 58%);color:inherit;padding:0 .1em;font:inherit;border-radius:0}

/* 생활 꿀팁 첫 화면 카드(10-14, 레이아웃 4안 = 상·하 분할 + 팝아웃 오브젝트. 위 미색 무대(::before) · 아래 흰 글자 영역): 점선 단계 바는 그대로.
   카드(.cd) = 옅은 미색 면, 배경 없는(투명 PNG/SVG) 오브젝트가 카드 위로 살짝 튀어나옴. 세로 길이 늘림 */
body .life-page .tp-flc{gap:0}
body .life-page .tp-flow{margin-top:clamp(44px,4.6vw,64px)} /* 위 설명 문구와 점선 단계 바 사이 여백 넓힘(10-14) */
body .life-page .tp-sec .sh + .hst{margin-top:clamp(20px,2.4vw,32px)} /* 주제 제목(어느 동에 살면…)과 01 소제목 사이 여백 넓힘(10-14) */
body .life-page #tp-food .sh + .fdbar{margin-top:clamp(20px,2.4vw,32px)} /* 먹거리: 제목과 식당/카페 버튼 사이 여백(10-14) */
