body .life-page .tp-flc .cd{position:relative;flex:1;display:flex;flex-direction:column;gap:8px;margin-top:104px;padding:0 24px 22px;border-radius:24px;background:#fff;box-shadow:0 0 0 1px #EBE9E4;transition:box-shadow .3s}
body .life-page .tp-flc .cd::before{content:"";position:absolute;left:0;right:0;top:0;height:150px;border-radius:24px 24px 0 0;background:#F6F6F3}
body .life-page .tp-flc:hover .cd{box-shadow:0 0 0 1px #E1DED7,0 18px 40px -22px rgba(0,0,0,.25)}
