body .life-page .tp-flc:focus-visible{border-radius:24px}
@media (max-width:860px){body .life-page .tp-flc .cd::before{height:130px}body .life-page .tp-flc .cd{margin-top:96px}body .life-page .tp-flc .ph{width:192px;height:192px;margin:-110px auto 48px}}
@media (max-width:560px){body .life-page .tp-flc .cd{margin-top:62px;padding:0 12px 14px;border-radius:16px}body .life-page .tp-flc .cd::before{height:78px;border-radius:16px 16px 0 0;background:#F6F6F3}body .life-page .tp-flc .ph{width:108px;height:108px;margin:-66px auto 36px}body .life-page .tp-flc em{margin-top:8px}body .life-page .tp-flc .go{font-size:12.5px}}

/* =========================================================
   인사교 알아보기 글자 위계(10-14, 전달본 교체 후): 디자인시스템(AI-Log) 글꼴 표에 맞춤
   - 큰 장 제목(h2) = h2-section Paperlogy 38/46 600   - 묶음 제목(h3) = Paperlogy 30/40 600(모바일 24)
   - 키커 = kicker Paperlogy 14.5 700 primary + 앞 24px 막대   - 카드 제목 = card-title-lg 20/30 600 · 큰 카드 card-title-xb 24/32 800 · 작은 카드 card-title 17/25 600
   - 본문 = Pretendard(lead 17 · body 16 · body-sm 14 · caption 13)   - 표지(히어로) · 큰 숫자는 그대로
   ========================================================= */
html.school-about main :is(p, li, dd, dt, small, blockquote, figcaption, td, th){font-family:var(--ff-sans)}
/* 큰 장 제목 */
html.school-about main :is(#intro-heading, #learning-heading, #activities-heading, #career-heading, #why-school-heading){font-family:var(--ff-text)!important;font-size:clamp(28px,2.7vw,38px)!important;line-height:1.22!important;font-weight:600!important;letter-spacing:-.025em!important;color:var(--ink)}
/* 장 제목 아래 한 줄 */
html.school-about main :is(.why-school-heading, .common-courses-heading, .guest-lecture-heading, .career-guide-heading) > p{font-family:var(--ff-sans)!important;font-size:17px!important;line-height:1.75!important;font-weight:400!important;letter-spacing:-.01em;color:var(--graphite)}
/* 묶음 제목 */
html.school-about main :is(.partner-heading h3, .graduate-stats-heading h4, .education-hours-heading h3, .daily-routine-heading h3, .activity-projects-heading h3, .activity-other-heading h3, .career-programs-heading h3, #eligibility-heading){font-family:var(--ff-text)!important;font-size:clamp(24px,2.2vw,30px)!important;line-height:1.33!important;font-weight:600!important;letter-spacing:-.025em!important;color:var(--ink)}
html.school-about main .partner-heading h3 + *, html.school-about main .daily-routine-heading > p{font-family:var(--ff-sans)!important}
/* 키커(짧은 이름 + 앞 막대) */
html.school-about main :is(.micro-label, .graduate-eyebrow, .activity-projects-heading > span, .activity-other-heading > span, .career-programs-heading > span){display:inline-flex!important;align-items:center;gap:10px;font-family:var(--ff-text)!important;font-size:14.5px!important;line-height:1.3!important;font-weight:700!important;letter-spacing:.02em!important;color:var(--primary)!important;text-transform:none}
html.school-about main :is(.micro-label, .graduate-eyebrow, .activity-projects-heading > span, .activity-other-heading > span, .career-programs-heading > span)::before{content:""!important;display:block!important;position:static!important;flex:none;width:24px!important;height:3px!important;border-radius:2px;background:var(--primary-bright)!important;margin:0!important}
/* 카드 제목 */
html.school-about main :is(.intro-news-story-copy h4, .intro-news-body h4, .intro-platform-features article h4, .common-course-caption h3, .education-phase-band h4, .daily-routine-agenda h4, .activity-project-body h4, .career-stage-copy h3){font-family:var(--ff-text)!important;font-size:20px!important;line-height:1.5!important;font-weight:600!important;letter-spacing:-.02em!important}
html.school-about main :is(.partner-node h4){font-family:var(--ff-text)!important;font-size:17px!important;line-height:1.47!important;font-weight:600!important;letter-spacing:-.01em!important}
html.school-about main :is(.why-school-card h4, .eligibility-condition h4, .career-program-hero h4){font-family:var(--ff-text)!important;font-size:24px!important;line-height:1.34!important;font-weight:800!important;letter-spacing:-.035em!important}
html.school-about main :is(.career-program-detail h5){font-family:var(--ff-text)!important;font-size:15px!important;font-weight:700!important}
html.school-about main :is(.cohort-topic-label, .why-school-highlight-label){font-family:var(--ff-text)!important;font-weight:600!important}
html.school-about main :is(.cohort-topic-label){font-size:13.5px!important}
/* 카드 안 설명 · 메모 = 본문 글꼴 */
html.school-about main :is(.career-program-summary, .career-program-meta, .graduate-stats-note, .cohort-card-header > span){font-family:var(--ff-sans)!important}
html.school-about main .career-program-summary{font-size:15px!important;line-height:1.7!important}
@media (max-width:760px){
  html.school-about main :is(.why-school-card h4, .eligibility-condition h4, .career-program-hero h4){font-size:21px!important}
  html.school-about main :is(.why-school-heading, .common-courses-heading, .guest-lecture-heading, .career-guide-heading) > p{font-size:16px!important}
}

/* 지원 전 CHECK 배너 위 여백(10-14): 선배들의 이야기 · 라이프 배너와 같게 = sec-y-first + 탭 자리 36px(1100px 이하는 탭이 없어 sec-y-first만) */
.check-page .ckx.cb{padding-top:0}
.check-page .ckx.cb>.wrap{padding-top:calc(var(--sec-y-first) + 36px)}
@media (max-width:1100px){.check-page .ckx.cb>.wrap{padding-top:var(--sec-y-first)}}

/* 프로젝트 카드 맨 아래 팀 줄(10-14): 오른쪽 끝 정렬(프로젝트 목록 · 이야기 첫 화면 같게) */
.stories-page .pjc .pjc-tx > .team,.stories-page .hb-pjc .hb-pjc-tx > .hb-pjc-tm{align-self:flex-end;text-align:right}

/* 기수별 이모저모 기수 원(10-14): '7기' 묶음을 원 한가운데로(전에는 위 22% 띄움이라 숫자가 위로 치우침). 숫자 · '기'는 같은 기준선, 숫자 글자 모양 기준으로 세로 가운데 */
.stories-page .cv3-ring>span{display:grid;grid-auto-flow:column;place-content:center;align-items:baseline;gap:2px;padding:0;box-sizing:border-box}
.stories-page .cv3-ring b{display:block;transform:translateY(.13em)}

/* 기수별 이모저모 게시물 창(10-14): 글이 짧아 오른쪽이 비어 보여 비율 조정 — 사진 칸을 넓히고(남는 폭 전부), 글 칸은 300px로 좁히고, 창 높이를 낮춤. 글자는 한 단계 키움 */
@media (min-width:761px){
  .stories-page .cv3-m-box{width:min(760px,100%);height:min(400px,calc(100vh - 160px))}
  .stories-page .cv3-m-media{flex:1 1 auto}
  .stories-page .cv3-m-side{flex:0 0 300px}
}
.stories-page .cv3-m-body{padding:18px 20px}
.stories-page .cv3-m-body h3{margin:0 0 10px;font-size:16.5px;line-height:1.5}
.stories-page .cv3-m-body p{font-size:15px;line-height:1.75;color:#3A3F4A}

/* 인사교 라이프 전체(#pg-home) 생활 꿀팁 섹션 = 인덱스 리스트(10-14): 카드 대신 한 줄씩. 번호 · 단계 · 제목 · 작은 사진 · 화살표 */
body .life-page .lo-tl{margin-top:clamp(24px,2.6vw,36px);border-top:1.5px solid var(--ink)}
body .life-page .lo-tr{display:grid;grid-template-columns:64px 150px minmax(0,1fr) 168px 40px;gap:28px;align-items:center;padding:22px 16px;border-bottom:1px solid #E6E8EC;color:var(--ink);text-decoration:none;transition:background .25s}
body .life-page .lo-tr:hover{background:#F6F7F9}
body .life-page .lo-tr .n{font:600 17px/1 var(--ff-text);font-variant-numeric:tabular-nums;color:#9CA3AF;transition:color .25s}
body .life-page .lo-tr:hover .n{color:var(--ink)}
body .life-page .lo-tr .w{display:flex;align-items:center;gap:10px;font:600 15px/1.2 var(--ff-text)}
body .life-page .lo-tr .w i{flex:none;width:8px;height:8px;border-radius:50%}
body .life-page .lo-tr .tx{display:flex;flex-direction:column;gap:6px;min-width:0}
body .life-page .lo-tr em{font:600 13px/1 var(--ff-text);font-style:normal;color:var(--primary)}
body .life-page .lo-tr b{font:600 22px/1.35 var(--ff-text);letter-spacing:-.02em;transition:color .2s}
body .life-page .lo-tr:hover b{color:var(--primary)}
body .life-page .lo-tr small{font:400 14px/1.4 var(--ff-sans);color:var(--muted)}
body .life-page .lo-tr .ph{display:block;}
body .life-page .lo-tr .ph img{display:block;width:100%;height:100%;}
body .life-page .lo-tr .arr{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;border:1px solid #E6E8EC;background:#fff;color:#374151;transition:.25s}
body .life-page .lo-tr:hover .arr{background:var(--ink);border-color:var(--ink);color:#fff}
body .life-page .lo-tr:focus-visible{outline:3px solid var(--primary);outline-offset:-3px}
@media (max-width:860px){body .life-page .lo-tr{grid-template-columns:40px minmax(0,1fr) 120px;gap:18px;padding:18px 8px}body .life-page .lo-tr .w,body .life-page .lo-tr .arr{display:none}}
@media (max-width:560px){body .life-page .lo-tr{grid-template-columns:26px minmax(0,1fr) 88px;gap:12px;padding:16px 4px}body .life-page .lo-tr .n{font-size:14px}body .life-page .lo-tr b{font-size:17px}body .life-page .lo-tr small{font-size:13px}}
body .life-page .lo-tr .ph{height:120px;border-radius:0;background:none;overflow:visible} /* 생성 이미지(투명 배경) 사용(10-14) */
body .life-page .lo-tr .ph img{object-fit:contain;transition:transform .5s cubic-bezier(.2,.8,.2,1)}
body .life-page .lo-tr:hover .ph img{transform:translateY(-4px) scale(1.04)}
@media (max-width:860px){body .life-page .lo-tr .ph{height:92px}}
@media (max-width:560px){body .life-page .lo-tr .ph{height:72px}}

/* 푸터 색(10-14): 모든 페이지(알아보기 포함) = 랜딩 푸터와 같은 차콜(#2B2D31, home.css와 같은 값) */
html:is([data-menu="stories"],[data-menu="life"],[data-menu="check"],[data-menu="about"]) .site-footer{background:#2B2D31;border-top-color:rgba(255,255,255,.12);color:rgba(255,255,255,.62)}
html:is([data-menu="stories"],[data-menu="life"],[data-menu="check"],[data-menu="about"]) .site-footer :is(.logo,.footer-links a){color:#fff}
html:is([data-menu="stories"],[data-menu="life"],[data-menu="check"],[data-menu="about"]) .site-footer .footer-links a:hover{color:#8AA9FF}
html:is([data-menu="stories"],[data-menu="life"],[data-menu="check"],[data-menu="about"]) .site-footer .logo-mark{background-image:url("../assets/brand/symbol-white.png")}
html:is([data-menu="stories"],[data-menu="life"],[data-menu="check"],[data-menu="about"]) .site-footer :is(a,button):focus-visible{outline-color:#8AA9FF}

/* 시설 둘러보기 끝 관련 링크(.fsx, 10-14): 위 정보 카드(흰 카드 + 그림자)와 구분 — 위 구분선 + "함께 보면 좋아요" 라벨, 그림자 없는 회색 판 + 화살표 원(라이프 전체 줄 목록 화살표와 같은 모양) */
html .life-page .fsx{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:clamp(40px,4vw,56px)!important;padding-top:clamp(24px,2.4vw,32px);border-top:1px solid var(--line)}
html .life-page .fsx::before{content:"함께 보면 좋아요";grid-column:1/-1;margin-bottom:-2px;font:600 15px/1.2 var(--ff-text);color:var(--ink)}
html .life-page .fsx > a{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto;column-gap:16px;row-gap:6px;align-items:center;padding:22px 22px 22px 26px;border:0!important;border-radius:16px!important;background:#F3F5F8!important;box-shadow:none!important;color:var(--ink);text-decoration:none;transition:background .25s,transform .25s cubic-bezier(.22,.61,.36,1)}
html .life-page .fsx > a span{grid-column:1;grid-row:1;flex:none;font:500 13px/1.3 var(--ff-sans);color:var(--graphite)}
html .life-page .fsx > a b{grid-column:1;grid-row:2;font:700 18px/1.4 var(--ff-text);letter-spacing:-.02em;transition:color .2s}
html .life-page .fsx > a i{grid-column:2;grid-row:1/3;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;border:1px solid #E6E8EC;background:#fff;color:#374151;font:600 15px/1 var(--ff-sans);transition:.25s}
html .life-page .fsx > a:hover{background:#EAF0FF!important;transform:translateY(-2px)}
html .life-page .fsx > a:hover b{color:var(--primary)}
html .life-page .fsx > a:hover i{background:var(--ink);border-color:var(--ink);color:#fff}
