}

/* 손글씨: 밝은 사진 위에서도 읽히게 그림자 */
.hand{text-shadow:0 2px 0 var(--ax-line),0 0 14px rgba(0,0,0,.65)}
.hand path{filter:drop-shadow(0 2px 0 var(--ax-line))}

/* 키워드 스티커 · 원형 마커는 이제 링크: 올리면 그 카테고리 색으로(기존 하이라이트) + 살짝 들림 */
.kw:hover{translate:0 -2px}
.mk:hover span{background:var(--hm-primary)}

/* 터치 화면(마우스 올리기 없음): 평소엔 넓은 화면과 같은 흑백 포스터, 문이 차례로 하나씩 깨어남(10-14 사용자 C안)
   - home.js가 01 → 02 → 03 → 04 → 오시는 길 순서로 1.5초씩 data-active를 돌림 → 넓은 화면 '올렸을 때' 규칙(컬러 · 카테고리 색 테두리)을 그대로 씀
   - 04는 상자가 원래 연두라 네모 칸에 차례로 체크 표시, 오시는 길은 지도 컬러 + 파랑 테두리 · 단추
   - 누르는 순간(:active)도 컬러. 움직임 줄이기 설정이면 돌지 않고 처음부터 컬러(전 방식) */
@media (hover:none){
  .tl:not(.hq-map):active img{filter:none}
  .ax[data-active="5"] .hq-map{border-color:var(--hq)}
  .ax[data-active="5"] .hq-map img,.hq-map:active img{filter:grayscale(.2) contrast(1.05)}
  .ax[data-active="5"] .map-go{background:var(--hq)}
  .checkbox li i{transition:background .25s}
  .checkbox li i::after{content:"";position:absolute;left:3px;top:-1px;width:4px;height:8px;border:solid var(--n-lime);border-width:0 2.5px 2.5px 0;transform:rotate(40deg);opacity:0;transition:opacity .2s}
  .ax[data-active="4"] .checkbox li i{background:#111}
  .ax[data-active="4"] .checkbox li i::after{opacity:1}
  .ax[data-active="4"] .checkbox li:nth-child(2) i,.ax[data-active="4"] .checkbox li:nth-child(2) i::after{transition-delay:.15s}
  .ax[data-active="4"] .checkbox li:nth-child(3) i,.ax[data-active="4"] .checkbox li:nth-child(3) i::after{transition-delay:.3s}
  .ax[data-active="4"] .checkbox li:nth-child(4) i,.ax[data-active="4"] .checkbox li:nth-child(4) i::after{transition-delay:.45s}
}
@media (hover:none) and (prefers-reduced-motion:reduce){
  .tl:not(.hq-map) img{filter:saturate(.92) contrast(1.04)}
  .hq-map img{filter:grayscale(.2) contrast(1.05)}
}

