/* 섹션 제목(자이언츠체): 페이지 제목(h1)보다 작게 — 시안 clamp(3.4 ~ 4.8 × --lr)는 1440에서 48px로 오시는 길 제목(36px)보다 크고, 390에서 꿀팁 제목과 같았음.
   2026-10-08 디자인 기준 5(h1 > h2 > 카드 제목): 1440 36 · 1100 29 · 860 22 · 390 27px(지원 전 체크 섹션 제목 28 ~ 38px과 같은 범위) */
.life-page #pg-facility .sh h2,
.life-page #pg-tips .sh h2,
.life-page #pg-way .sh h2{font-size:clamp(calc(2.6*var(--lr)),2.6vw,calc(3.6*var(--lr)));color:var(--ink)}
/* 카드 모서리: 사이트 공통 --r-card(16px, 공용 '다음으로' 띠와 같음) · 목록 안 작은 칸 10px · 작은 표시는 알약 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.wmap,.fsx a){border-radius:var(--r-card)!important}
.life-page :is(#pg-facility,#pg-tips,#pg-way) .walk{border-radius:999px}
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.walk){box-shadow:none}
/* 배지 · 버튼 · 칩: 스티커 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) .bdg{border-radius:calc(.4*var(--lr));font-weight:700}
.life-page :is(#pg-facility,#pg-tips,#pg-way) .bdg.base{background:var(--axl);color:var(--cat);font-family:var(--anton);font-weight:400}
.life-page :is(#pg-facility,#pg-tips,#pg-way) .bdg.part{background:var(--ny);color:var(--ink);border:1.5px solid var(--axl)}
.life-page #pg-facility .sh h2,.life-page #pg-tips .sh h2,.life-page #pg-way .sh h2{font-family:var(--jua);font-weight:700}
/* 고정 지도: 커진 카드가 헤더 아래로 숨지 않게 */
/* 위쪽 핀: 설명을 카드 아래로 */
/* 휴게 공간 임시 사진 */
