/* 5·18민주광장 사진 */
.life-page .im-plaza_tmp{background-image:url("../assets/plaza_tmp.webp");background-position:50% 45%}
/* 대인시장 사진 */
.life-page .im-mkt_tmp{background-image:url("../assets/mkt_tmp.webp");background-position:40% 35%}
/* 중외공원 사진 */
.life-page .im-park_tmp{background-image:url("../assets/park_tmp.webp");background-position:50% 55%}
/* 챔피언스 필드 사진 */
