/* ===== 생활 적응: 시간 순서 체크리스트 ===== */
/* 장식 점: 시안의 빈 네모는 눌리는 체크박스처럼 보였음(눌리지 않음) */
/* ===== 오시는 길: 지하철 · 버스 카드 여백 정리 ===== */
.life-page #pg-way .route{border:0;box-shadow:none;background:none;padding:0;margin-top:calc(1.8*var(--lr))}
.life-page #pg-way .route li{grid-template-columns:calc(3.2*var(--lr)) minmax(0,1fr);gap:calc(.2*var(--lr)) calc(1.4*var(--lr));padding-bottom:calc(2.4*var(--lr))}
.life-page #pg-way .route li:last-child{padding-bottom:0}
.life-page #pg-way .route li::before{left:calc(1.5*var(--lr));top:calc(3.6*var(--lr));bottom:calc(.4*var(--lr))}
.life-page #pg-way .route i{background:var(--card);color:var(--ink)}
.life-page #pg-way .route li:last-child i{background:var(--cat);color:var(--ink)}
.life-page #pg-way .route b{font-size:calc(1.6*var(--lr));line-height:1.35}
.life-page #pg-way .route span{display:block;margin-top:calc(.3*var(--lr));font-size:calc(1.35*var(--lr));line-height:1.5}
.life-page #pg-way .route em{grid-column:2;margin-top:calc(.8*var(--lr));justify-self:start;font-family:var(--sans);font-size:calc(1.2*var(--lr));font-weight:700;color:var(--ink);background:color-mix(in srgb,var(--cat) 22%,var(--card));padding:calc(.15*var(--lr)) calc(.7*var(--lr))}
.life-page #pg-way .route li:nth-child(2) em{display:none}
.life-page #pg-way .way .note{margin-top:calc(.4*var(--lr))}
/* 근처 식당 가격대 */
/* 가격대: 바탕 · 테두리 없이 ₩ 기호 + 글(시안의 연두 · 흰 뱃지 대신) */
/* ===== 주거: 요약 → 동별 비교 → 지원 ===== */
.life-page .hst{display:flex;align-items:center;flex-wrap:wrap;gap:calc(.4*var(--lr)) calc(1*var(--lr));margin:calc(3.6*var(--lr)) 0 calc(1.6*var(--lr));font-size:calc(1.9*var(--lr))}
.life-page .hst:first-of-type{margin-top:0}
.life-page .hst span{width:calc(3.8*var(--lr));height:calc(3.8*var(--lr));border-radius:50%;display:grid;place-items:center;background:var(--cat);color:var(--ink);font-weight:400;font-size:calc(1.6*var(--lr))}
.life-page .hst em{font-style:normal;font-size:calc(1.3*var(--lr));font-weight:700;color:var(--ink3)}
/* 근처 식당: 메뉴 종류 태그 */
/* 음식 갈래: 시안의 갈래별 7색 대신 한 결(강조색은 카테고리 청록 하나) */
/* ===== 문화·여가 크게 보기 ===== */
/* 크게 보기 유도 */
/* 동명동 카페거리 사진 */
.life-page .im-cafest{background-image:url("../assets/cafest.webp");background-position:25% 55%}
/* 푸른길 사진 */
.life-page .im-trailp{background-image:url("../assets/trailp.webp");background-position:45% 50%}
/* 광주천 사진 */
.life-page .im-riverp{background-image:url("../assets/riverp.webp");background-position:40% 55%}
/* 사직공원 사진 */
.life-page .im-sajikp{background-image:url("../assets/sajikp.webp");background-position:30% 55%}
/* 1) 카드 · 표 · 지도 틀: 굵은 검정 테두리 + 하드 그림자 → 얇은 회색 선 + 옅은 그림자 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.fd2c,.lmm,.wmap,.mpanel,.lmli,.adt,.hsc,.hmw,.hdl,.hac:not(.main),.adlk,.rt3 article){border:1px solid var(--bline)!important;box-shadow:var(--soft)!important;border-radius:var(--r-card)!important}
/* 2) 카드 안 제목: 자이언츠체 → 본문 굵은 글꼴 (자이언츠체는 첫 화면 · 섹션 제목에만) */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.fd2c h3,.hsch h3,.adt header h3,.hac b,.adlk b,.hst,#pg-way .mpanel h3){font-family:var(--sans)}
/* 3) 어두운 띠 · 검정 칩 → 옅은 색 */
.life-page .hst span{box-shadow:none}
.life-page #pg-way .route i,
.life-page .route i{border:1.5px solid var(--bline)!important}
.life-page #pg-way .route em{border:1px solid var(--bline)!important}
.life-page :is(#pg-facility,#pg-tips,#pg-way) .chip:not([aria-pressed="true"]){border:1px solid var(--bline)!important}
/* 4) 본문 글자 위계: 설명은 한 톤 옅게, 줄 간격 여유 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.walk){border:0;background:var(--paper);color:var(--ink2)}
/* 섹션 제목 자간 · 본문 줄 간격 · 보조 글 색 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) .sh h2{letter-spacing:-.015em;margin-top:0}
.life-page :is(#pg-facility,#pg-tips,#pg-way) p,
.life-page :is(#pg-facility,#pg-tips,#pg-way) li{line-height:1.75}
.life-page .note,
.life-page .fdisc{color:var(--ink3)}
/* 크게 보기 창 · '다음으로' 카드 · 버튼: 얇은 선 · 옅은 그림자 */
/* 본문 · 설명 · 표 · 버튼 · 메뉴 */
.life-page :is(#pg-facility,#pg-tips,#pg-way,.lnb) :is(p,li,dd,dt,small,span,a,button,em,figcaption){font-family:var(--sans)}
/* 카드 제목 · 굵은 글씨: 너무 두껍지 않게 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(b){font-weight:700}
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.fd2c h3,.hsch h3,.adt header h3,.hac b,.adlk b,.hst,#pg-way .mpanel h3,.lmli b,.hdt b,.fd2i b){font-weight:700;letter-spacing:-.02em}
/* 작은 라벨(예전 모노 글꼴)은 자간을 풀어 읽기 쉽게 */
.life-page :is(#pg-facility,#pg-tips,#pg-way) :is(.walk,.bdg,.src){letter-spacing:0}
/* 중요한 글자는 그대로: 첫 화면 · 큰 숫자 · 스티커 · 손글씨 */
.life-page .hst span{font-family:var(--anton)!important}
/* ===== 근처 식당 목록 안 스크롤 ===== */
/* 861px 이상에서만(5곳이 넘으면 목록 안 스크롤, life.js [16]). 860px 이하는 모두 펼침 — 폰에서 목록 안에 스크롤이 갇히던 것(2026-10-08).
   목록 끝에 닿으면 페이지가 이어서 스크롤(시안의 overscroll-behavior:contain 뺌) */
/* ===== 문화·여가 목록: 머리(가볼 곳 · n곳) + 목록 + 아래 줄 =====
   861px 이상: 상자 높이 = 옆 지도 칸(life.js [17]), 목록만 안에서 스크롤 · 아래 줄 '↓ n곳 더'. 860px 이하: 안 스크롤 없이 처음 5곳 + '나머지 n곳 더 보기'(2026-10-08) */
/* ===== 층별 · 공간별 안내(층 버튼 · 공간 · 사진 넘김 표시) ===== */
.life-page .bx9-tr{display:flex;height:100%;transition:transform .45s cubic-bezier(.22,.61,.36,1)}
.life-page .bx9-sl{flex:0 0 100%;height:100%;background-size:var(--bs,cover);background-position:var(--bp,center)!important;background-repeat:no-repeat}
/* 층 버튼 · 760px 이하: 비활성 층 글을 세로 가운데로 */

/* ===== 층 버튼 · 낮은 화면(861px 이상 · 높이 640px 이하): 버튼 위아래 여백 줄임 ===== */
/* ===== 생활 꿀팁 히어로(.h5 · .h5-tip, 시안5 '카테고리별 히어로') ===== */
.life-page .h5{position:relative;overflow:hidden}
/* 머리글: 시설 둘러보기 .fh8-k와 같은 모양(이동경로를 빼서 히어로 첫 줄) */
.life-page .h5 h1{font-family:var(--jua);font-weight:700;line-height:1.12;letter-spacing:-.01em;margin-top:calc(1*var(--lr));text-wrap:balance}
/* --- 생활 꿀팁 : 스크랩북 --- */
@media (max-width:600px){
.life-page .h5 h1{font-size:calc(3.4*var(--lr))}
}
/* --- 인사교 라이프 색(청록 --nc) 기준으로 맞춤 --- */
/* ===== 오시는 길 제목 줄(.pt7, 시안7 · 히어로 없는 페이지) ===== */
/* 2026-10-08: 머리글(.fh8-k) · 제목 · 설명(.fh8-s)을 시설 둘러보기 히어로와 같은 모양으로 — 제목이 아래 섹션 제목보다 작던 것(36 < 48px, 1440)을 페이지 제목 크기로(규칙은 아래 .fh8 h1과 같이 씀) */

/* 층 표시창: 문 위 가운데 */
/* ===== 시설 둘러보기 히어로: 공간 사진 벤토(.fh8, 시안8 v4) ===== */


/* ===== 사이트 통합 조정 (시안 밖, 공통 틀에 맞춘 값 · 2026-10-07) =====
   - 헤더: 시안의 자기 헤더(붙는 높이 7rem) 대신 공통 고정 헤더(--hdr: 72px, 860px 이하 60px) + 하위 메뉴 바(--sub). 2뎁스(시설 둘러보기 · 생활 꿀팁 · 오시는 길)는
     공통 하위 메뉴 바, 시안의 소메뉴 바(.lnb)는 생활 꿀팁의 01~04 바로가기만 남겨 그 밑에 붙임(.lnb의 top)
   - 가로: 본문 · 히어로 안 · 바로가기 막대 · '다음으로' · 안내문을 헤더와 같은 정렬선(공통 --wrap 1240px · 좌우 --gutter)으로. 값은 각 규칙(.wrap · .next .wrap ·
     .disc.inset · 아래 히어로 안 상자)에 있음. 시안 비율 단위 상자(124 · 150 × --lr)와 시안 자체 좌우 여백은 폭 · 여백에 쓰지 않음(글자 · 컴포넌트 크기는 --lr 그대로).
     100vw 대신 부모 폭 기준이라 스크롤바가 있어도 헤더와 같은 선
   - 세로: 공통 토큰(common/css/tokens.css) — 섹션 사이 --sec-y, 히어로(꿀팁은 바로가기 막대) 바로 다음 섹션 위 --sec-y-first, 히어로 안 위아래 --hero-y,
     '다음으로' 띠 위아래 --sec-y. 섹션 제목 위 여백은 이 토큰만(제목 margin-top 0). 라이프 .sec.alt 바탕(paper 55% + card)은 기본 바탕과 거의 같아
     (명도 대비 약 1.02 : 1) 띠로 읽히지 않음 → 띠 규칙 대신 섹션 사이를 --sec-y로(지원 전 체크와 같은 간격) 하고, 흐린 바탕 경계가 글에 붙지 않게 위아래 반씩
   - 문화·여가 지도(.lmw2)의 시안 sticky 규칙은 그대로 두지만 실제로는 붙지 않음 — 옆 목록(.lmlw)이 지도와 같은 높이에서 안쪽 스크롤이라 줄(.lmrow)에 붙을 여유가 없음 */
/* 히어로 바탕: 2026-10-07 사용자 결정(후보 B) — 카테고리 색(청록)을 연하게. 시안 생활 꿀팁의 연한 색(var(--primary-soft))과 같은 값 */

/* 히어로 안 상자: 정렬선 폭 · 위아래 --hero-y */
/* 꿀팁 히어로 점무늬: 안쪽 상자(.h5g)가 정렬선 폭으로 좁아지면 무늬 끝이 히어로 안에 세로 경계로 보여 히어로 전체 바탕으로 옮김(무늬 · 색 그대로) */
/* 꿀팁 히어로 칸 비율: 시안 1 : 1.1 대신 1 : 1(961px 이상, 960px 이하는 시안대로 한 칸). 상자가 정렬선 폭(1290 → 1144px, 1440 기준)으로 좁아져
   시안에서 한 줄이던 제목(「선배만 아는 인사교 생활 꿀팁」)이 '꿀팁'만 다음 줄로 떨어져서. 사진 칸은 574 → 548px. 글꼴이 달라 그래도 넘치면 두 줄을 고르게 */
.life-page .sec{padding-block:calc(var(--sec-y) / 2)}   /* 섹션 사이 = 앞 섹션 아래 반 + 이 섹션 위 반 = --sec-y */
.life-page :is(.lnb)+.sec{padding-top:var(--sec-y-first)}
/* '다음으로' 띠(공용 .next-band: 흰 바탕 · 위 선이 보이는 띠) 앞 마지막 섹션 아래 */
/* 안내문(꿀팁 끝): 왼쪽 선 포함 상자가 정렬선에서 시작. 바탕이 같은 마지막 섹션의 끝 줄이라 그 섹션 아래 여백은 0, '다음으로' 띠 앞 여백(--sec-y)은 안내문 아래로 옮김 */
.life-page .sec:has(+.disc.inset){padding-bottom:0}
/* 꿀팁 위치(#tp-house 등)로 갈 때(바로가기 · 주소 · 다른 화면 링크): 섹션 제목이 바로가기 막대 아래 32px.
   scroll-margin = 막대 높이 + 24px(32 - base.css scroll-padding의 8) - 섹션 위 여백 */
.life-page .tp-sec{scroll-margin-top:calc(var(--lnb-h) + 24px - var(--sec-y) / 2)}
.life-page .lnb+.tp-sec{scroll-margin-top:calc(var(--lnb-h) + 24px - var(--sec-y-first))}

/* ===== 시안10 추가(2026-10-08): 근처 식당 음식 종류 거르기 · 빈 상태, 주차 안내 제목 뺀 뒤 문장 ===== */
.life-page .fdempty{display:grid;justify-items:center;gap:12px;padding:40px 20px;border:1px dashed var(--line-s);border-radius:var(--r-card);background:var(--card);text-align:center;color:var(--ink2);font-weight:600}
.life-page .fdempty[hidden]{display:none!important}
/* 시안10 v4: 생활 꿀팁 바로가기 막대(.lnb)를 통째로 뺌 — 막대 높이 0, 히어로 바로 다음 섹션 위 여백은 다른 화면과 같게 */
.life-page{--lnb-h:0px}

/* ===== 시안10-B: 인사교 라이프 공통 히어로(.lh) 하나 · 하위 화면 히어로 없음 ===== */
/* 하위 메뉴 카드 3장: 누르면 그 화면으로 */
/* 하위 화면: 제목은 읽어 주는 기기에만(화면 이름은 하위 메뉴 바 · 위 카드가 보여 줌), 첫 섹션 위 여백은 히어로 다음과 같게 */
.life-page .lh-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.life-page .page>.lh-sr+.sec{padding-top:var(--sec-y-first)}
.life-page .page>.lh-sr+.tp-sec{scroll-margin-top:calc(24px - var(--sec-y-first))}

/* ===== 시안10-B v2: 히어로가 화면 한가득(헤더 · 하위 메뉴 바 아래 남은 높이 전부) ===== */
/* 카드는 화면 높이에 맞춰 키움: 사진 칸이 남은 높이를 채움 */

/* ===== 시안10-B v3: 히어로가 따로 된 페이지(#pg-home) — 히어로 아래 본문 없음, 카드는 하위 화면으로 가는 입구 ===== */
.life-page #pg-home{min-height:0}

/* ===== 시안10-B v7: 히어로 하위 메뉴를 펼치는 패널로(.lh-p · .lhp) — 올리거나 초점이 가면 그 패널이 넓어지며 설명 · 항목 · 이동 버튼이 보임 ===== */
/* 960px 이하: 펼치기 없이 세 줄 카드(사진 바탕 + 제목 + 한 줄 설명 + 화살표) */

/* 단독 시안(2026-10-12): 세 하위 화면 끝 '다음으로' 띠(.next-band) 삭제 — 화면 마지막 섹션 아래 여백을 띠 앞과 같게(--sec-y) */
.life-page .page>.sec:last-child{padding-bottom:var(--sec-y)}

/* 단독 시안(2026-10-12): 주거 — 시세 · 월세 금액 대신 '집이 모여 있는 곳'(밀집 개념도 + 동별 모인 정도 · 형태) */

/* 단독 시안(2026-10-12): 근처 먹거리 — 식당 · 카페 카드(사진 자리 + 이름 · 메뉴 · 가격대 + 선배 후기), 거르기는 전체 · 혼밥 · 여럿이 · 도보 10분 안 */
.life-page .fdg{display:grid;list-style:none;margin:0;padding:0}
.life-page .fdc{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--bline);border-radius:var(--r-card);background:var(--card);box-shadow:var(--soft)}
.life-page .fdc-ph{position:relative;aspect-ratio:16/10;display:grid;place-items:center;background-color:color-mix(in srgb,var(--nc) 16%,var(--card));background-image:repeating-linear-gradient(135deg,transparent 0 14px,color-mix(in srgb,var(--nc) 22%,transparent) 14px 15px)}
.life-page .fdc-cat{position:absolute;left:12px;top:12px;border-radius:999px;background:var(--ink);color:#fff;font-weight:700}
.life-page .fdc-wk{position:absolute;right:12px;bottom:12px;border-radius:999px;background:rgba(255,255,255,.92);color:var(--ink);font-weight:700}
.life-page .fdc-g{font-size:12.5px;font-weight:700;color:var(--primary)}
.life-page .fdc-g.group{color:var(--ink2)}
.life-page .fdc-b h3{margin-top:4px;font-weight:700;letter-spacing:-.02em;line-height:1.35}
.life-page .fdc-m{margin-top:2px;color:var(--ink2)}
.life-page .fdc-r{border-radius:10px;background:var(--paper)}
.life-page .fdc-r figcaption{display:flex;align-items:center;gap:6px;font-size:12.5px;font-weight:700;color:var(--ink)}
.life-page .fdc-r blockquote{position:relative;margin:6px 0 0;padding-left:14px;color:var(--ink)}
.life-page .fdc-r blockquote::before{content:"";position:absolute;left:0;top:.2em;bottom:.2em;width:3px;border-radius:2px;background:var(--nc)}
.life-page .fdmore2{display:flex;justify-content:center;margin-top:calc(2.4*var(--lr))}
.life-page .fdmore2[hidden]{display:none!important}

/* 단독 시안(2026-10-12): 문화 · 여가 — 세 갈래 묶음. 접힘: 사진 카드가 비스듬히 겹친 더미 / 펼침: 가로로 늘어선 카드(사진 + 이름 · 거리 · 요금 · 한 줄) */
.life-page .fs{display:flex;flex-direction:column;gap:16px}
.life-page .fsg{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:24px 32px;align-items:center;padding:24px 28px;border:1px solid var(--bline);border-radius:var(--r-card);background:var(--card);box-shadow:var(--soft);transition:padding .4s}
.life-page .fsh{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px 14px;align-items:start}
.life-page .fsn{grid-row:1/3;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:var(--nc);color:var(--ink);font-family:var(--anton);font-size:18px}
.life-page .fsh h3{font-size:20px;font-weight:700;letter-spacing:-.02em;line-height:1.35}
.life-page .fsh p{margin-top:2px;font-size:14px;color:var(--ink2)}
.life-page .fs-tg{grid-column:2;justify-self:start;display:inline-flex;align-items:center;gap:8px;margin-top:10px;height:38px;padding:0 16px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--ink);font-size:14px;font-weight:700;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.life-page .fs-tg svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.life-page .fs-tg:hover{border-color:var(--ink)}
.life-page .fs-tg .c{display:none}
.life-page .fsg.is-open .fs-tg{background:var(--ink);border-color:var(--ink);color:#fff}
.life-page .fsg.is-open .fs-tg .o{display:none}
.life-page .fsg.is-open .fs-tg .c{display:inline}
.life-page .fs-tg:focus-visible{border-radius:999px}
/* 더미 · 펼침 */
.life-page .fsd{position:relative;min-width:0;cursor:pointer}
.life-page .fsg.is-open .fsd{cursor:default}
.life-page .fsl{display:flex;align-items:flex-start;list-style:none;margin:0;padding:10px 0 10px 6px}
.life-page .fsc{position:relative;z-index:var(--z);flex:0 0 200px;min-width:0;margin-left:-172px;display:flex;flex-direction:column;overflow:hidden;border-radius:12px;background:var(--card);border:4px solid #fff;box-shadow:0 10px 24px -12px rgba(20,35,63,.45);transform:rotate(var(--rt));transition:flex .55s cubic-bezier(.22,.61,.36,1),margin .55s cubic-bezier(.22,.61,.36,1),transform .55s cubic-bezier(.22,.61,.36,1),border-width .3s,box-shadow .3s}
.life-page .fsc:first-child{margin-left:0}
.life-page .fsd:hover .fsc{transform:rotate(calc(var(--rt) * 1.6)) translateX(calc(var(--i) * 6px))}
.life-page .fsc-ph{display:block;aspect-ratio:4/3;background-size:cover;background-position:center}
.life-page .fsc-b{grid-template-rows:0fr;opacity:0;transition:opacity .3s}
.life-page .fsg.is-open{grid-template-columns:1fr;padding:24px 28px 28px}
.life-page .fsg.is-open .fsh{grid-template-columns:auto minmax(0,1fr) auto;align-items:center}
.life-page .fsg.is-open .fsn{grid-row:auto}
.life-page .fsg.is-open .fs-tg{grid-column:3;margin-top:0}
.life-page .fsg.is-open .fsl{gap:16px;padding:0;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:thin}
.life-page .fsg.is-open .fsc{flex:1 1 0;min-width:200px;margin-left:0;transform:none;border-width:1px;border-color:var(--bline);box-shadow:none;scroll-snap-align:start}
.life-page .fsg.is-open .fsc-b{flex-direction:column;gap:2px;padding:12px 14px 14px;opacity:1;transition-delay:.25s}
.life-page .fsc-b b{font-size:15.5px;font-weight:700;line-height:1.35}
.life-page .fsc-b small{font-size:12.5px;font-weight:700;color:var(--primary)}
.life-page .fsc-t{align-self:flex-start;margin-top:4px;padding:1px 8px;border-radius:999px;background:var(--paper-2);font-size:11.5px;font-weight:700;color:var(--ink2)}
.life-page .fsc-d{margin-top:6px;font-size:13px;line-height:1.6;color:var(--ink2)}
@media (max-width:860px){
.life-page .fsg{grid-template-columns:1fr;padding:20px}
.life-page .fsg.is-open .fsh{grid-template-columns:auto minmax(0,1fr)}
.life-page .fsg.is-open .fs-tg{grid-column:2;margin-top:6px}
.life-page .fsg.is-open .fsc{flex:0 0 72%;min-width:0}}
@media (max-width:600px){
.life-page .fsc{flex-basis:150px;margin-left:-128px}
}
@media (prefers-reduced-motion:reduce){
.life-page .fsc,.life-page .fsc-b{transition:none}}
/* ===== 문화·여가 v10b: 접힌 카드 = 사진만 · 덱 옆에 장소 이름 미리보기 ===== */
.life-page .fsd{display:flex;align-items:center;gap:20px 36px}
.life-page .fsl{flex:none}
.life-page .fsc-b{display:none}
.life-page .fsg.is-open .fsd{display:block}
.life-page .fsg.is-open .fsc-b{display:flex;}
@keyframes fsIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.life-page .fs-side{display:flex;flex-direction:column;align-items:flex-start;gap:14px;min-width:0}
.life-page .fs-names{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.life-page .fs-names li{position:relative;padding-left:14px;font-size:14.5px;font-weight:600;color:var(--ink);line-height:1.45}
.life-page .fs-names li::before{content:"";position:absolute;left:0;top:.6em;width:6px;height:6px;border-radius:50%;background:var(--nc)}
.life-page .fsg.is-open .fs-side{display:none}
@media (max-width:600px){
.life-page .fsd{flex-direction:column;align-items:flex-start}
.life-page .fs-side{flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px}
.life-page .fs-names{flex-direction:row;flex-wrap:wrap;gap:4px 12px}
.life-page .fs-names li{font-size:13px}
}
@media (max-width:860px){.life-page .fsg.is-open{padding:20px}}

/* ===== 주거 v11: 「자취방 수」 + 월세 평균(2026년 기준 · 조사 후 채움) ===== */

/* ===== 주거 v12: 지도와 동 목록 크기 맞춤 ===== */

/* ===== 근처 먹거리 v13: 식당 · 카페 탭 + 카드 그리드(v7 카드로 복귀) ===== */
#tp-food .sh{margin-bottom:calc(1.6*var(--lr))}
.life-page .fdbar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px 20px;margin-bottom:calc(2.2*var(--lr))}
.life-page .fdk{display:inline-flex;gap:4px;padding:4px;border-radius:999px;background:var(--card);border:1px solid var(--bline);box-shadow:var(--soft)}
.life-page .fdk-b{display:inline-flex;align-items:center;gap:8px;height:44px;padding:0 22px;border:0;border-radius:999px;background:transparent;color:var(--ink2);font-size:16px;font-weight:700;cursor:pointer;transition:background .2s,color .2s}
.life-page .fdk-b span{font-family:var(--anton);font-weight:400;font-size:14px;color:var(--ink3);letter-spacing:.02em}
.life-page .fdk-b:hover{color:var(--ink)}
.life-page .fdk-b[aria-selected="true"]{background:var(--ink);color:#fff}
.life-page .fdk-b[aria-selected="true"] span{color:var(--nc)}
.life-page .fdk-b:focus-visible{outline:3px solid var(--primary);outline-offset:2px}
.life-page .fdbar .r{margin:0}
.life-page .fdg[hidden]{display:none!important}
@media (max-width:600px){
.life-page .fdbar{flex-direction:column;align-items:stretch}
.life-page .fdk{display:flex}
.life-page .fdk-b{flex:1;justify-content:center;height:42px}}

/* ===== 오시는 길 v14: 지하철 · 버스 오는 길 삭제(주요 이동 경로와 겹침) → 개념도를 한 줄 전체 폭으로 ===== */
.life-page #pg-way .way{grid-template-columns:1fr}
.life-page #pg-way .wmap svg{aspect-ratio:1120/420;height:auto}
@media (max-width:600px){.life-page #pg-way .wmap svg{aspect-ratio:auto;height:280px}}

/* ===== 오시는 길 v15: 개념도 옆에 건물 사진(찾기 쉽게) ===== */
.life-page #pg-way .wmap-v{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(0,1fr);height:400px}
.life-page #pg-way .wmap-v svg{aspect-ratio:auto;width:100%;height:100%;min-width:0}
.life-page #pg-way .wbld{position:relative;margin:0;min-width:0;overflow:hidden;border-left:1px solid var(--line);background:#0E1522}
.life-page #pg-way .wbld-ph{position:absolute;inset:0;background-size:cover;background-position:center 35%}
.life-page #pg-way .wbld-in{position:absolute;right:14px;top:14px;width:34%;aspect-ratio:4/3;border:3px solid #fff;border-radius:10px;background-size:cover;background-position:center 70%;box-shadow:0 8px 20px -8px rgba(0,0,0,.5)}
.life-page #pg-way .wbld-in span{position:absolute;left:0;right:0;bottom:0;padding:2px 6px;background:rgba(14,21,34,.72);color:#fff;font-size:11px;font-weight:700;text-align:center}
.life-page #pg-way .wbld figcaption{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;gap:2px;padding:44px 18px 16px;background:linear-gradient(transparent,rgba(10,16,32,.82));color:#fff}
.life-page #pg-way .wbld figcaption b{font-size:17px;font-weight:800}
.life-page #pg-way .wbld figcaption span{font-size:13px;opacity:.9;line-height:1.5}
.life-page #pg-way .wbld figcaption a{align-self:flex-start;margin-top:6px;font-size:13px;font-weight:700;color:var(--nc);border-bottom:1px solid currentColor}
@media (max-width:860px){
.life-page #pg-way .wmap-v{grid-template-columns:1fr;height:auto}
.life-page #pg-way .wmap-v svg{height:280px}
.life-page #pg-way .wbld{aspect-ratio:4/3;border-left:0;border-top:1px solid var(--line)}}
@media (max-width:600px){.life-page #pg-way .wmap-v svg{height:260px}}

/* ===== 시설 둘러보기: 위 여백(제목 · 건물 단면 · 사진이 한 화면에) ===== */
.life-page #pg-facility .fac-sec{padding-top:clamp(20px,3svh,40px)}

/* ===== 주거 v24: 집이 모여 있는 곳 — 걷는 시간 막대 + 동별 카드(개념도 · 줄 목록 대신) ===== */
.life-page .hz2{display:flex;flex-direction:column;gap:18px}
/* 카드 */
.life-page .hzc-h{display:flex;align-items:center;flex-wrap:wrap;gap:6px 8px}
.life-page .hzc-h b{font-size:19px;font-weight:800;letter-spacing:-.02em}
.life-page .hzc-here{padding:1px 7px;border-radius:999px;background:var(--nc);color:var(--ink);font-size:11px;font-weight:800}
.life-page .hzc-s{font-size:12.5px;line-height:1.45;color:var(--ink2)}
.life-page .hzm{display:inline-flex;gap:3px;margin-right:3px}
.life-page .hzm i{width:16px;height:6px;border-radius:3px;background:var(--primary)}
.life-page .hzm i.off{background:var(--line)}
.life-page .hzt{padding:2px 9px;border-radius:999px;background:var(--paper-2,#EEF1F3);font-size:12.5px;font-weight:700;color:var(--ink2)}
.life-page .hzc-rent{margin-top:auto;padding:10px 12px;border-radius:10px;background:var(--paper)}
.life-page .hzc-rent dd{flex-direction:column;align-items:flex-start;gap:2px}
