.life-page .fsg.fs-flip .fsc{background-color:transparent;border-color:transparent;box-shadow:none}
.life-page .fsg:not(.fs-flip) .fsc{transition:flex .55s cubic-bezier(.22,.61,.36,1),margin .55s cubic-bezier(.22,.61,.36,1),transform .55s cubic-bezier(.22,.61,.36,1),border-width .3s,box-shadow .3s,background-color .3s,border-color .3s}
.life-page .fsg.fs-flip .fsc-ph{box-shadow:0 10px 24px -12px rgba(20,35,63,.45);border-radius:8px}
.life-page .fsh{position:relative;z-index:6}

/* ===== 근처 먹거리 v32: PC 4열 × 2줄(8곳), 1100px 이하 3열 · 860px 이하 2열 · 600px 이하 1열, 후기 2줄 ===== */
.life-page .fdg{grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.life-page .fdc-b{padding:14px 16px 10px}
.life-page .fdc-b h3{font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.life-page .fdc-m{font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.life-page .fdc-r{margin:auto 12px 12px;padding:10px 12px}
.life-page .fdc-r blockquote{font-size:13.5px;line-height:1.55;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;min-height:3.1em}
