@media (max-width:1100px){.life-page .fdg{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:860px){.life-page .fdg{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:600px){.life-page .fdg{grid-template-columns:1fr;gap:14px}.life-page .fdc-b h3{font-size:18px}}

/* ===== 주거 v35: 교육장 가운데 개념 지도(걷는 시간 막대 대신) ===== */
.life-page .hzmw{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:0;border:1px solid var(--bline);border-radius:var(--r-card);background:var(--card);box-shadow:var(--soft);overflow:hidden}
.life-page .hzmw-map{position:relative;min-width:0;background:#F3F5F2}
.life-page .hzmap2{display:block;width:100%;height:auto;}
.life-page .hm-bg{fill:#F3F5F2}
.life-page .hm-rd{fill:none;stroke:#fff;stroke-width:58;stroke-linecap:round;stroke-linejoin:round}
