stories/css/cohort-v3.css:
/* 기수별 이모저모 — 선배들의 이야기 v3 시안(인스타 프로필형). 값은 시안 그대로, 메인 파랑 #2457F5 */
.stories-page .cv3{--cv-b2:#8AA9FF;--cv-ink:#262626;--cv-line:#DBDBDB}
/* 기수 칩(위에 붙어 따라옴) */
.stories-page .cv3-chips{position:sticky;top:calc(var(--hdr,72px) + 8px);z-index:5;display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:14px 0;margin-bottom:32px;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line,#D3D9E1)}
.stories-page .cv3-chips button{display:inline-flex;align-items:center;gap:6px;height:40px;padding:0 16px;border-radius:999px;border:1px solid var(--line,#D3D9E1);background:#fff;color:var(--graphite,#566175);font:600 15px/1 var(--ff-sans);cursor:pointer;transition:border-color .2s,color .2s}
.stories-page .cv3-chips button:hover{border-color:var(--ink,#14233F);color:var(--ink,#14233F)}
.stories-page .cv3-chips button[aria-selected="true"]{border-color:var(--ink,#14233F);background:var(--ink,#14233F);color:#fff}
.stories-page .cv3-chips button i{width:8px;height:8px;border-radius:50%;background:var(--cv-b)}
.stories-page .cv3-chips button[aria-selected="true"] i{background:#fff}
/* 프로필 */
.stories-page .cv3-ig{max-width:935px;margin:0 auto;font-family:var(--ff-sans);color:var(--cv-ink)}
.stories-page .cv3-prof{display:flex;align-items:center;gap:clamp(24px,6vw,88px);padding:8px clamp(0px,4vw,56px) 32px}
.stories-page .cv3-ring{flex:none;aspect-ratio:1;border-radius:50%;}
.stories-page .cv3-ring>span{justify-content:center;width:100%;height:100%;border-radius:50%;}
.stories-page .cv3-info{flex:1;display:flex;flex-direction:column;align-items:flex-start;gap:14px;min-width:0}
.stories-page .cv3-r1{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.stories-page .cv3-acc{font-size:22px;font-weight:600;letter-spacing:0}
.stories-page .cv3-tag{display:inline-flex;align-items:center;height:32px;padding:0 14px;border-radius:8px;background:#EFEFEF;font-size:13.5px;font-weight:600}
.stories-page .cv3-dbtn{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 14px;border-radius:8px;border:0;background:var(--cv-b);color:#fff;font:600 13.5px/1 var(--ff-sans);cursor:pointer}
.stories-page .cv3-dbtn:hover{filter:brightness(1.08)}
.stories-page .cv3-stat{display:flex;flex-wrap:wrap;gap:6px clamp(16px,3vw,40px);font-size:16px}
.stories-page .cv3-stat b{font-weight:700}
.stories-page .cv3-bio{margin:0;font-size:14.5px;line-height:1.6}
.stories-page .cv3-bio b{font-weight:700}
/* 달라진 점 표 */
.stories-page .cv3-diff{margin:0 clamp(0px,4vw,56px) 28px;padding:4px 20px;border-radius:12px;background:#F5F7F6;overflow-x:auto}
.stories-page .cv3-dt{display:grid;grid-template-columns:minmax(80px,110px) minmax(0,1fr) minmax(0,1.3fr);min-width:520px;font-size:14px;line-height:1.55}
.stories-page .cv3-dt>*{padding:11px 12px;border-bottom:1px solid #E9EEF3}
.stories-page .cv3-dt>b{padding-left:0;font-weight:700}
.stories-page .cv3-dt>s{color:var(--muted);text-decoration-color:rgba(138,144,155,.5)}
.stories-page .cv3-dt>span{font-weight:600}
.stories-page .cv3-dt>:nth-last-child(-n+3){border-bottom:0}
/* 달별 하이라이트 */
.stories-page .cv3-hl{display:flex;gap:clamp(14px,3vw,36px);padding:0 clamp(0px,4vw,56px) 28px;overflow-x:auto;scrollbar-width:none;}
.stories-page .cv3-hl::-webkit-scrollbar{display:none}
.stories-page .cv3-hl button{flex:none;display:flex;flex-direction:column;align-items:center;gap:8px;width:84px;padding:0;border:0;background:none;cursor:pointer;color:var(--cv-ink);font-family:var(--ff-sans)}
.stories-page .cv3-hr{display:block;width:78px;height:78px;border-radius:50%;padding:3px;background:var(--cv-line);transition:background .2s}
.stories-page .cv3-hr>span{position:relative;display:block;width:100%;height:100%;border-radius:50%;border:3px solid #fff;overflow:hidden;background:#E9EEF3}
.stories-page .cv3-hr .illu{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.stories-page .cv3-hl button[aria-pressed="true"] .cv3-hr{background:linear-gradient(45deg,var(--cv-b),var(--cv-b2))}
.stories-page .cv3-hl button:hover .cv3-hr{background:#BFC6D1}
.stories-page .cv3-hl button[aria-pressed="true"]:hover .cv3-hr{background:linear-gradient(45deg,var(--cv-b),var(--cv-b2))}
.stories-page .cv3-hl b{font-size:12.5px;font-weight:500;line-height:1.2}
.stories-page .cv3-hl button[aria-pressed="true"] b{font-weight:700}
.stories-page .cv3-hl small{margin-top:-6px;font-size:11.5px;color:#8E8E8E}
/* 격자 */
.stories-page .cv3-gt{display:flex;justify-content:center;align-items:center;gap:6px;width:fit-content;margin:-1px auto 0;padding:14px 0;border-top:1px solid var(--cv-ink);font-size:12.5px;font-weight:700;letter-spacing:.08em;color:var(--cv-ink)}
.stories-page .cv3-gt svg{width:13px;height:13px;fill:none;stroke:var(--cv-ink);stroke-width:2}
.stories-page .cv3-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}
.stories-page .cv3-it{position:relative;display:block;aspect-ratio:1;overflow:hidden;background:repeating-linear-gradient(135deg,#E9EEF3 0 10px,#F5F7F6 10px 20px);text-decoration:none}
.stories-page .cv3-it .illu{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .4s}
.stories-page .cv3-it:hover .illu{transform:scale(1.03)}
.stories-page .cv3-reel{position:absolute;top:10px;right:10px;width:22px;height:22px;fill:none;stroke:#fff;stroke-width:2;filter:drop-shadow(0 1px 2px rgba(0,0,0,.4))}
.stories-page .cv3-ov{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;padding:clamp(10px,1.6vw,18px);background:linear-gradient(rgba(11,16,32,0) 35%,rgba(11,16,32,.82));color:#fff;text-align:left;opacity:0;transition:opacity .2s}
.stories-page .cv3-ov b{font:700 clamp(13px,1.3vw,16px)/1.35 var(--ff-text)}
.stories-page .cv3-ov span{font:400 12px/1.3 var(--ff-sans);color:rgba(255,255,255,.8)}
.stories-page .cv3-it:is(:hover,:focus-visible) .cv3-ov{opacity:1}
/* 페이지 */
.stories-page .cv3-pg{display:flex;flex-direction:column;align-items:center;gap:12px;margin-top:48px}
.stories-page .cv3-pgr{display:flex;justify-content:center;gap:6px}
.stories-page .cv3-pgr button{min-width:40px;height:40px;padding:0 6px;border-radius:999px;border:1px solid #DDE0E5;background:#fff;color:var(--graphite);font:700 14px/1 var(--ff-sans);cursor:pointer}
.stories-page .cv3-pgr button[aria-current="page"]{border-color:#2B2D31;background:#2B2D31;color:#fff}
.stories-page .cv3-pgr button:disabled{opacity:.35;cursor:default}
.stories-page .cv3-pg p{margin:0;font:400 13px/1.4 var(--ff-sans);color:var(--muted)}
/* 글 창 */
.cv3-lock,.cv3-lock body{overflow:hidden}
.cv3-m{position:fixed;inset:0;z-index:200;display:flex;align-items:center;justify-content:center;padding:24px}
.cv3-m[hidden]{display:none}
.cv3-m-bg{position:absolute;inset:0;background:rgba(11,16,32,.6)}
.cv3-m-box{position:relative;display:flex;width:min(940px,100%);height:min(470px,calc(100vh - 160px));background:#fff;border-radius:6px;overflow:hidden;box-shadow:0 30px 60px -20px rgba(0,0,0,.5)}
