.cv3-play i{position:absolute;left:27px;top:21px;border-style:solid;border-width:13px 0 13px 21px;border-color:transparent transparent transparent #14233F}
.cv3-m-side{flex:1;display:flex;flex-direction:column;min-width:0;font-family:var(--ff-sans);color:#262626}
.cv3-m-hd{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid #EFEFEF}
.cv3-av{justify-content:center;width:34px;height:34px;padding-top:5px;border-radius:50%;}

.cv3-m-acc{font-size:14.5px;font-weight:600}
.cv3-m-x{margin-left:auto;width:32px;height:32px;border:0;background:none;font-size:24px;line-height:1;color:#262626;cursor:pointer}
.cv3-m-body{flex:1;overflow:auto;padding:16px}
.cv3-m-body h3{margin:0 0 8px;font:700 15px/1.45 var(--ff-text)}
.cv3-m-body h3 b{font-family:var(--ff-sans);font-weight:600;margin-right:2px}
.cv3-m-body p{margin:0;font-size:14.5px;line-height:1.65}
.cv3-m-ft{padding:10px 16px 14px;border-top:1px solid #EFEFEF}
.cv3-m-act{display:flex;justify-content:space-between}
