.stories-page .rev:has(#fco_2:checked) .dw-fco summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#fco_2:checked) .dw-fco label[for=fco_2]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#fco_3:checked) .dw-fco summary b{display:none}
.stories-page .rev:has(#fco_3:checked) .dw-fco summary u::after{content:"4기"}
.stories-page .rev:has(#fco_3:checked) .idc:not(.coh4),
.stories-page .rev:has(#fco_3:checked) .rvr:not(.coh4){display:none}
.stories-page .rev:has(#fco_3:checked) .dw-fco summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#fco_3:checked) .dw-fco label[for=fco_3]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#fco_4:checked) .dw-fco summary b{display:none}
.stories-page .rev:has(#fco_4:checked) .dw-fco summary u::after{content:"3기"}
.stories-page .rev:has(#fco_4:checked) .idc:not(.coh3),
