.stories-page .rev:has(#fco_4:checked) .dw-fco summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#fco_4:checked) .dw-fco label[for=fco_4]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#fco_all:checked) .dw-fco label[for=fco_all]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#tg-0:target) .idc:not(.tg0),
.stories-page .rev:has(#tg-0:target) .rvr:not(.tg0){display:none}
.stories-page .rev:has(#tg-0:target) .dw-ftg summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#tg-0:target) .dw-ftg summary b{display:none}
.stories-page .rev:has(#tg-0:target) .dw-ftg summary u::after{content:"#비전공자"}
.stories-page .rev:has(#tg-0:target) .dw-ftg a[href="#tg-0"]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#tg-1:target) .idc:not(.tg1),
