.stories-page .rev:has(#tg-1:target) .dw-ftg summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#tg-1:target) .dw-ftg summary b{display:none}
.stories-page .rev:has(#tg-1:target) .dw-ftg summary u::after{content:"#타지출신"}
.stories-page .rev:has(#tg-1:target) .dw-ftg a[href="#tg-1"]{color:var(--g900);font-weight:600}
.stories-page .rev:has(#tg-2:target) .idc:not(.tg2),
