.stories-page .rev:has(#tg-2:target) .dw-ftg summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#tg-2:target) .dw-ftg summary b{display:none}
.stories-page .rev:has(#tg-2:target) .dw-ftg summary u::after{content:"#직장인출신"}
.stories-page .rev:has(#tg-2:target) .dw-ftg a[href="#tg-2"]{color:var(--g900);font-weight:600}
