.stories-page .rev:has(#tg-5:target) .rvr:not(.tg5){display:none}
.stories-page .rev:has(#tg-5:target) .dw-ftg summary{background:var(--g900);color:#fff}
.stories-page .rev:has(#tg-5:target) .dw-ftg summary b{display:none}
