.stories-page .rev:has(#tg-6:target) .dw-ftg a[href="#tg-6"]{color:var(--g900);font-weight:600}
.stories-page .rev:not(:has(.tgt:target)) .dw-ftg a[href="#p-rev"]{color:var(--g900);font-weight:600}
/* 모달 태그 — 누르면 창이 닫히며 그 태그의 후기만 남는다 */
.stories-page .ov .mtags .t{
  line-height:28px;transition:var(--ease)}
.stories-page .ov .mtags .hint{width:100%;margin-top:8px;line-height:19px}
/* 섹션 머리 오른쪽에 보기 전환 */
.stories-page .sh-row{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:flex-end}
.stories-page .vtoggle{display:inline-flex;gap:2px}
.stories-page .vtoggle label{display:grid;place-items:center;cursor:pointer;color:var(--g600);transition:var(--ease)}
/* 글자는 지우되 읽어 주는 기기에는 남긴다 */
.stories-page .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);
  clip-path:inset(50%);white-space:nowrap}
.stories-page .vtoggle label:hover{color:var(--g900)}
.stories-page .vtoggle svg{width:16px;height:16px}
.stories-page .rev:has(#vm-card:checked) .vtoggle label[for=vm-card],
.stories-page .rev:has(#vm-list:checked) .vtoggle label[for=vm-list]{background:var(--g900);color:#fff}
/* 보기 전환 — 둘 중 하나만 */
.stories-page .rev:has(#vm-list:checked) .idgrid{display:none}
.stories-page .rev:not(:has(#vm-list:checked)) .rvlist{display:none}
/* 쪽 번호 — 필터가 걸리면 쪽 나눔 없이 결과를 다 보여 준다 */
.stories-page .rev:has(#rc_all:checked):has(#fco_all:checked):not(:has(.tgt:target)):has(#pgn1:checked) .idc:not(.pg1),
.stories-page .rev:has(#rc_all:checked):has(#fco_all:checked):not(:has(.tgt:target)):has(#pgn1:checked) .rvr:not(.pg1){display:none}
.stories-page .rev:has(#rc_all:checked):has(#fco_all:checked):not(:has(.tgt:target)):has(#pgn2:checked) .idc:not(.pg2),
.stories-page .rev:has(#rc_all:checked):has(#fco_all:checked):not(:has(.tgt:target)):has(#pgn2:checked) .rvr:not(.pg2){display:none}
.stories-page .rev:has(#rc_all:checked):has(#fco_all:checked):not(:has(.tgt:target)):has(#pgn3:checked) .idc:not(.pg3),
